    "sha256": "2f4e98817f09a1a97d24201358f1aea47f4d9b504223f777c43251cf90e0b8b2",
    "text": "{% load static %}<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#023171\"><title>{% block title %}Family Dollar Operations{% endblock %} \u00b7 S3PL</title><link rel=\"stylesheet\" href=\"{% static 'app.css' %}\"><script src=\"{% static 'brand/globe-motion.js' %}\" defer></script><script src=\"{% static 'brand/pallet-wrapper.js' %}\" defer></script></head>\n<body class=\"portal-page\"><a class=\"skip-link\" href=\"#main-content\">Skip to content</a>\n<header class=\"portal-header\"><a class=\"brand\" href=\"{% url 'dashboard' %}\" aria-label=\"S3PL operations home\">{% include 'brand/globe.html' %}<span class=\"brand-copy\"><b class=\"brand-name\">Superior 3rd Party Logistics</b><span class=\"brand-caption\">CUSTOMER OPERATIONS</span></span></a><div class=\"header-account\"><span class=\"account-name\">{{ request.user.get_full_name|default:request.user.username }}</span><span class=\"badge role-badge\">{% if is_warehouse %}Warehouse{% else %}FD Corporate{% endif %}</span><form method=\"post\" action=\"{% url 'logout' %}\">{% csrf_token %}<button class=\"text-button\">Sign out <svg viewBox=\"0 0 24 24\" width=\"1em\" height=\"1em\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" style=\"display:inline-block;vertical-align:-.1em;flex:0 0 1em\"><path d=\"M6 18 18 6M6 6h12v12\"/></svg></button></form></div></header>\n<aside class=\"sidebar\" aria-label=\"Workspace\"><div class=\"workspace\"><svg class=\"fd-workspace-logo\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"320 275 570 585\" width=\"64\" height=\"66\" role=\"img\" aria-label=\"Family Dollar\" style=\"display:block;flex:0 0 64px;background:white;border-radius:8px;padding:6px;box-sizing:content-box\"><title>Family Dollar</title><metadata>Family Dollar logo; Tellermate 2021, via Wikimedia Commons; CC BY-SA 4.0. https://commons.wikimedia.org/wiki/File:Family-Dollar-Logo-2.png ; https://creativecommons.org/licenses/by-sa/4.0/ . Display viewport trimmed.</metadata><image width=\"1189\" height=\"1147\" href=\"data:image/png;base64,\"/></svg><div><span class=\"workspace-label\">YOUR WORKSPACE</span><strong>Family Dollar</strong><small>Inventory &amp; fulfillment</small></div></div>\n<nav aria-label=\"Main navigation\"><span class=\"nav-section\">OPERATIONS</span>\n<a href=\"{% url 'dashboard' %}\" {% if request.path == '/' %}class=\"active\" aria-current=\"page\"{% endif %}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z\"/></svg>Overview</a>\n<a href=\"{% url 'inventory' %}\" {% if '/inventory/' in request.path or '/parts/' in request.path or '/bins/' in request.path %}class=\"active\" aria-current=\"page\"{% endif %}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m12 3 9 5-9 5-9-5 9-5ZM3 8v9l9 5 9-5V8M12 13v9M7 5.8l9 5\"/></svg>Inventory</a>\n<a href=\"{% url 'orders' %}\" {% if '/orders/' in request.path %}class=\"active\" aria-current=\"page\"{% endif %}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 3h12v18H6zM9 8h6M9 12h6M9 16h4\"/></svg>Orders</a>\n<a href=\"{% url 'alerts' %}\" {% if '/alerts/' in request.path %}class=\"active\" aria-current=\"page\"{% endif %}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M18 8a6 6 0 0 0-12 0c0 7-3 8-3 8h18s-3-1-3-8M9 20h6\"/></svg>Stock alerts</a>\n{% if is_warehouse %}<span class=\"nav-section\">WAREHOUSE</span><a href=\"{% url 'purchase_orders' %}\">Purchase orders</a>\n<a href=\"{% url 'receipts' %}\" {% if '/receipts/' in request.path %}class=\"active\" aria-current=\"page\"{% endif %}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12m-4-4 4 4 4-4M4 14v7h16v-7\"/></svg>Receiving</a>\n<a href=\"{% url 'work_queue' %}\" {% if '/work/' in request.path %}class=\"active\" aria-current=\"page\"{% endif %}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m3 6 2 2 4-4m3 2h9M3 13l2 2 4-4m3 2h9M3 20l2 2 4-4m3 2h9\"/></svg>Warehouse tasks</a>\n<a href=\"{% url 'inventory' %}?counted=no\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 2M4 17l2 2a7 7 0 0 0 12-2\"/></svg>Cycle counts</a>\n<a href=\"{% url 'history' %}\" {% if '/history/' in request.path %}class=\"active\" aria-current=\"page\"{% endif %}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></svg>Activity history</a>{% endif %}</nav>\n<div class=\"sidebar-foot\"><span class=\"location-pin\" aria-hidden=\"true\">\u25ce</span><div><strong>Middle Tennessee</strong><small>Superior 3rd Party Logistics</small></div></div></aside>\n<div class=\"main\"><div class=\"workspace-bar\"><span>FAMILY DOLLAR <span aria-hidden=\"true\">/</span> OPERATIONS PORTAL</span><a href=\"https://s3pl-company.s3pl-nashvil-8733.chatgpt.site\" target=\"_blank\" rel=\"noopener\">Visit S3PL <svg viewBox=\"0 0 24 24\" width=\"1em\" height=\"1em\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" style=\"display:inline-block;vertical-align:-.1em;flex:0 0 1em\"><path d=\"M6 18 18 6M6 6h12v12\"/></svg></a></div>\n<main id=\"main-content\">{% for message in messages %}<div class=\"notice {{ message.tags }}\" role=\"status\">{{ message }}</div>{% endfor %}{% block content %}{% endblock %}</main><footer><span>Superior 3rd Party Logistics</span><span>Family Dollar \u00b7 WMS update 2026.11.12</span></footer></div></body></html>\n"
  },
