    "sha256": "94768b541ac31681ff3c856d0b7d36d8884793a9f361018cc6ee0292aa74d700",
    "text": "{% load static %}<span class=\"globe-logo\" role=\"img\" aria-label=\"S3PL globe logo \u2014 Distribution, Logistics, Solutions\"><svg class=\"line-globe\" viewBox=\"0 0 1254 1254\" aria-hidden=\"true\"><defs><mask id=\"original-ink\"><rect width=\"1254\" height=\"1254\" fill=\"white\"/><circle cx=\"630\" cy=\"610\" r=\"452\" fill=\"black\"/><rect x=\"160\" y=\"455\" width=\"960\" height=\"295\" fill=\"white\" transform=\"rotate(-13 630 610)\"/></mask><mask id=\"globe-grid\"><circle cx=\"630\" cy=\"610\" r=\"452\" fill=\"white\"/><rect x=\"150\" y=\"455\" width=\"980\" height=\"295\" fill=\"black\" transform=\"rotate(-13 630 610)\"/></mask></defs><g mask=\"url(#globe-grid)\" fill=\"none\" stroke=\"#023171\" stroke-width=\"30\"><g transform=\"rotate(-13 630 610)\"><circle cx=\"630\" cy=\"610\" r=\"430\"/><path d=\"M259 391H1001 M259 829H1001\"/><path class=\"rotating-meridian\" d=\"M630.0,172.0 L605.2,172.9 L580.5,175.7 L556.0,180.4 L531.8,186.9 L508.1,195.2 L484.8,205.3 L462.2,217.2 L440.3,230.7 L419.3,245.8 L399.1,262.5 L379.9,280.7 L361.8,300.3 L344.8,321.2 L329.1,343.4 L314.6,366.7 L301.5,391.0 L289.8,416.3 L279.6,442.4 L270.8,469.2 L263.6,496.6 L258.0,524.6 L253.9,552.8 L251.5,581.4 L250.7,610.0 L251.5,638.6 L253.9,667.2 L258.0,695.4 L263.6,723.4 L270.8,750.8 L279.6,777.6 L289.8,803.7 L301.5,829.0 L314.6,853.3 L329.1,876.6 L344.8,898.8 L361.8,919.7 L379.9,939.3 L399.1,957.5 L419.3,974.2 L440.3,989.3 L462.2,1002.8 L484.8,1014.7 L508.1,1024.8 L531.8,1033.1 L556.0,1039.6 L580.5,1044.3 L605.2,1047.1 L630.0,1048.0\"/><path class=\"rotating-meridian\" d=\"M630.0,172.0 L630.0,172.9 L630.0,175.7 L630.0,180.4 L630.0,186.9 L630.0,195.2 L630.0,205.3 L630.0,217.2 L630.0,230.7 L630.0,245.8 L630.0,262.5 L630.0,280.7 L630.0,300.3 L630.0,321.2 L630.0,343.4 L630.0,366.7 L630.0,391.0 L630.0,416.3 L630.0,442.4 L630.0,469.2 L630.0,496.6 L630.0,524.6 L630.0,552.8 L630.0,581.4 L630.0,610.0 L630.0,638.6 L630.0,667.2 L630.0,695.4 L630.0,723.4 L630.0,750.8 L630.0,777.6 L630.0,803.7 L630.0,829.0 L630.0,853.3 L630.0,876.6 L630.0,898.8 L630.0,919.7 L630.0,939.3 L630.0,957.5 L630.0,974.2 L630.0,989.3 L630.0,1002.8 L630.0,1014.7 L630.0,1024.8 L630.0,1033.1 L630.0,1039.6 L630.0,1044.3 L630.0,1047.1 L630.0,1048.0\"/><path class=\"rotating-meridian\" d=\"M630.0,172.0 L654.8,172.9 L679.5,175.7 L704.0,180.4 L728.2,186.9 L751.9,195.2 L775.2,205.3 L797.8,217.2 L819.7,230.7 L840.7,245.8 L860.9,262.5 L880.1,280.7 L898.2,300.3 L915.2,321.2 L930.9,343.4 L945.4,366.7 L958.5,391.0 L970.2,416.3 L980.4,442.4 L989.2,469.2 L996.4,496.6 L1002.0,524.6 L1006.1,552.8 L1008.5,581.4 L1009.3,610.0 L1008.5,638.6 L1006.1,667.2 L1002.0,695.4 L996.4,723.4 L989.2,750.8 L980.4,777.6 L970.2,803.7 L958.5,829.0 L945.4,853.3 L930.9,876.6 L915.2,898.8 L898.2,919.7 L880.1,939.3 L860.9,957.5 L840.7,974.2 L819.7,989.3 L797.8,1002.8 L775.2,1014.7 L751.9,1024.8 L728.2,1033.1 L704.0,1039.6 L679.5,1044.3 L654.8,1047.1 L630.0,1048.0\"/></g></g><image href=\"{% static 'brand/s3pl-logo.png' %}\" width=\"1254\" height=\"1254\" mask=\"url(#original-ink)\"/></svg></span>\n"
