  "templates/dashboard.html": {
    "previous": [
      "7cb80e04de5a6965c44c1ca1dbdecc9855ceee87b191ed12edbc6aa99dde664b",
      "5c0f55542b9055fc723188784da91386d21971edbf60b87b1d38bf88968f66b2"
    ],
    "sha256": "4e6045c07ec8ba1f905b89499238ba5207af7024ce9dfc3ae59e6597ca9d842f",
    "text": "{% extends 'base.html' %}{% block content %}<div class=\"page-title\"><div><p class=\"eyebrow\">YOUR OPERATION AT A GLANCE</p><h1>Operations overview</h1><p>Inventory, requests, and fulfillment in one place.</p></div><div class=\"page-actions\">{% if is_warehouse %}<a class=\"button secondary\" href=\"{% url 'receipt_new' %}\">New receipt <span aria-hidden=\"true\">\u2193</span></a>{% endif %}<a class=\"button\" href=\"{% url 'new_order' %}\">New order <span aria-hidden=\"true\">+</span></a></div></div>\n<div class=\"metrics\"><article><span>Active parts</span><strong>{{ parts }}</strong><small>Family Dollar catalog</small></article><article><span>Part / bin records</span><strong>{{ locations }}</strong><small>Pick locations &amp; overstock</small></article><article><span>Open orders</span><strong>{{ open_orders }}</strong><small>Submitted or awaiting shipment</small></article><article class=\"amber\"><span>Awaiting a count</span><strong>{{ uncounted }}</strong><small>Excluded from available stock</small></article></div>\n<div class=\"overview-notices\"><div class=\"notice\"><a href=\"{% url 'alerts' %}\"><strong>{{ low_stock }}</strong> low-stock items <span aria-hidden=\"true\">\u2192</span></a></div><div class=\"notice\">Availability reflects posted, counted inventory. Review opening counts before using the portal for live orders.</div></div>\n<section class=\"panel\"><div class=\"section-title\"><div><p class=\"eyebrow\">ORDER ACTIVITY</p><h2>Recent orders</h2></div><a href=\"{% url 'orders' %}\">View all orders <svg viewBox=\"0 0 24 24\" width=\"1em\" height=\"1em\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" style=\"display:inline-block;vertical-align:-.1em;flex:0 0 1em\"><path d=\"M6 18 18 6M6 6h12v12\"/></svg></a></div>{% include 'order_table.html' %}</section>\n<div class=\"two-col overview-bottom\"><section class=\"panel inventory-feature\"><p class=\"eyebrow\">INVENTORY CONTROL</p><h2>A clear view of<br>what\u2019s available.</h2><p>Counted on-hand stock, reservations, and availability. Every part, across pick and overstock locations.</p><a class=\"button secondary\" href=\"{% url 'inventory' %}\">Explore inventory <svg viewBox=\"0 0 24 24\" width=\"1em\" height=\"1em\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" style=\"display:inline-block;vertical-align:-.1em;flex:0 0 1em\"><path d=\"M6 18 18 6M6 6h12v12\"/></svg></a><div class=\"feature-rule\"><span>ON HAND</span><span>RESERVED</span><span>AVAILABLE</span></div></section><section class=\"panel fulfillment-feature\"><div><p class=\"eyebrow\">FROM DOCK TO DESTINATION</p><h2>Keep things moving.</h2><p>Follow requests through picking, packing, and shipping.</p><a class=\"text-link\" href=\"{% url 'orders' %}\">Open fulfillment queue <svg viewBox=\"0 0 24 24\" width=\"1em\" height=\"1em\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" style=\"display:inline-block;vertical-align:-.1em;flex:0 0 1em\"><path d=\"M6 18 18 6M6 6h12v12\"/></svg></a></div>{% include 'brand/pallet_wrapper.html' %}</section></div>{% endblock %}\n"
  },
  "templates/inventory.html": {
    "previous": [
      "11676531cd1baae42bb18ab5384519f64d73a08b23e310c9b0dc1efbe84e100a"
    ],
    "sha256": "1041e9df0686c8e953a1ffafdd9f67d93343df1b96cec3cd203782076c0d62f0",
    "text": "{% extends 'base.html' %}{% load static %}{% block content %}<script src=\"{% static 'inventory.js' %}\" defer></script><div class=\"page-title\"><div><p class=\"eyebrow\">INVENTORY CONTROL</p><h1>Inventory</h1><p>Recorded balances, allocations, and availability by location.</p><small id=\"refresh-status\" role=\"status\">Updates every 30 seconds while this page is open.</small></div><div><a class=\"button secondary\" href=\"{% url 'inventory_export' %}\">Export CSV</a>{% if is_warehouse %} <a class=\"button\" href=\"{% url 'new_bin' %}\">Add part / bin</a>{% endif %}</div></div>\n<form class=\"filters\"><input type=\"search\" name=\"q\" value=\"{{ q }}\" placeholder=\"Search part, description, or bin\" aria-label=\"Search inventory\"><select name=\"kind\" aria-label=\"Location type\"><option value=\"\">All locations</option><option value=\"PICK\" {% if kind == 'PICK' %}selected{% endif %}>Pick locations</option><option value=\"OVERSTOCK\" {% if kind == 'OVERSTOCK' %}selected{% endif %}>Overstock</option></select><select name=\"counted\" aria-label=\"Count status\"><option value=\"\">All count statuses</option><option value=\"no\" {% if counted == 'no' %}selected{% endif %}>Uncounted</option></select><button>Search</button><a href=\"{% url 'inventory' %}\">Clear</a></form>\n<section id=\"part-totals\" class=\"panel table-wrap\"><h2>Warehouse totals by part</h2><p>On hand includes bins and staged goods. Allocated includes reserved and staged goods. Available excludes allocations and quality holds. Backorders are not allocated.</p><table><tr><th>Part</th><th>On hand</th><th>Allocated</th><th>Available</th><th>Staged</th><th>Held</th><th>Backordered</th></tr>{% for r in summaries %}<tr><td>{{ r.part.sku }}</td><td>{{ r.on_hand|floatformat:'-3' }}{% if r.unknown %}<small>Plus {{ r.unknown }} uncounted bins</small>{% endif %}</td><td>{{ r.allocated|floatformat:'-3' }}</td><td>{{ r.available|floatformat:'-3' }}</td><td>{{ r.staged|floatformat:'-3' }}</td><td>{{ r.held|floatformat:'-3' }}</td><td>{{ r.backordered|floatformat:'-3' }}</td></tr>{% endfor %}</table><small>Totals cover all locations for parts shown on this page; filters below apply to bin rows.</small></section><section class=\"panel flush\"><div class=\"table-wrap\"><table><thead><tr><th>Part / description</th><th>Location</th><th>Type</th><th class=\"num\">In bin</th><th class=\"num\">Reserved</th><th class=\"num\">Available</th>{% if is_warehouse %}<th>Actions</th>{% endif %}</tr></thead><tbody>{% for s in page %}<tr><td><strong class=\"mono\">{{ s.part.sku }}</strong><small>{{ s.part.description|default:'Description not supplied' }}</small><small>{{ s.part.unit|default:'Unit unverified' }} \u00b7 {{ s.part.pack_description }}</small></td><td class=\"mono\">{{ s.location.code }}</td><td><span class=\"badge {% if s.kind == 'PICK' %}pick{% endif %}\">{{ s.get_kind_display }}</span>{% if s.held %}<small class=\"uncounted\">On hold: {{ s.hold_reason }}</small>{% endif %}</td><td class=\"num\">{% if s.on_hand is None %}<span class=\"uncounted\">Uncounted</span>{% else %}{{ s.on_hand|floatformat:'-3' }}{% if not s.last_counted_at and not s.count_required %}<small class=\"uncounted\">Provisional \u2014 no physical count recorded</small>{% endif %}{% if s.count_required %}<small class=\"uncounted\">Needs count</small>{% endif %}{% endif %}</td><td class=\"num\">{{ s.reserved|floatformat:'-3' }}</td><td class=\"num\">{% if s.available is None %}\u2014{% else %}<strong>{{ s.available|floatformat:'-3' }}</strong><small>{{ s.available_packs }}</small>{% endif %}</td>{% if is_warehouse %}<td class=\"actions\"><a href=\"{% url 'part_settings' s.part_id %}\">Item settings</a><a href=\"{% url 'stock_edit' s.pk %}\">Count / hold</a><a href=\"{% url 'transfer' s.pk %}\">Transfer</a></td>{% endif %}</tr>{% empty %}<tr><td colspan=\"7\" class=\"empty\">No matching inventory records.</td></tr>{% endfor %}</tbody></table></div></section>{% include 'pagination.html' %}<p class=\"muted\">Availability excludes bins marked for counting or held. Provisional test balances remain orderable until reconciled. Refresh to see the latest warehouse updates.</p>{% endblock %}\n"
  },
  "templates/new_order.html": {
    "previous": [
      "10d74a5775df4acec1482ae1389c46cf5d1e81deb072fe7a8e40fe15bf5f97ad"
    ],
    "sha256": "cb927cab7483023344a0998b0873e8e44fa64b0e55575bc3d260cc4eea584ecf",
    "text": "{% extends 'base.html' %}{% load static %}{% block content %}<div class=\"page-title\"><div><p class=\"eyebrow\">DIRECT CORPORATE ORDERING</p><h1>New order</h1><p>Submit a request for a store. Available inventory is allocated when submitted.</p></div></div>{% if error %}<div class=\"notice error\" role=\"alert\">{{ error }}</div>{% endif %}<p><a class=\"button secondary\" href=\"{% url 'order_upload' %}\">Upload Excel / CSV orders for multiple stores</a></p><form method=\"post\" id=\"order-form\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><section class=\"panel\"><h2>Store & delivery details</h2>{% include 'store_lookup.html' %}{{ form.non_field_errors }}{% for hidden in form.hidden_fields %}{{ hidden }}{{ hidden.errors }}{% endfor %}<div class=\"form-grid\">{% for field in form.visible_fields %}<div><label for=\"{{ field.id_for_label }}\">{{ field.label }}</label>{{ field }}{{ field.errors }}</div>{% endfor %}</div></section><section class=\"panel\"><h2>Requested parts</h2><p class=\"muted\">Search by part number or description and enter whole EA quantities. Available inventory is allocated when you submit. Shipments can go out in parts; shortages stay open and release automatically when accepted stock arrives.</p><datalist id=\"parts\">{% for p in catalog %}<option value=\"{{ p.sku }}\">{{ p.description }} \u00b7 {{ p.pack_description }}</option>{% endfor %}</datalist><div id=\"lines\">{% for sku,qty,uom in selected %}<div class=\"order-line\"><label>Part<input name=\"sku\" value=\"{{ sku }}\" list=\"parts\" required></label><label>Quantity<input name=\"quantity\" type=\"number\" min=\"1\" step=\"1\" value=\"{{ qty }}\" required></label><label>Unit<input value=\"EA\" readonly aria-label=\"Eaches\"><input type=\"hidden\" name=\"unit\" value=\"EA\"></label><button type=\"button\" class=\"secondary remove-line\">Remove</button></div>{% empty %}<div class=\"order-line\"><label>Part<input name=\"sku\" list=\"parts\" placeholder=\"Search part number\" required></label><label>Quantity<input name=\"quantity\" type=\"number\" min=\"1\" step=\"1\" required></label><label>Unit<input value=\"EA\" readonly aria-label=\"Eaches\"><input type=\"hidden\" name=\"unit\" value=\"EA\"></label><button type=\"button\" class=\"secondary remove-line\">Remove</button></div>{% endfor %}</div><button type=\"button\" class=\"secondary\" id=\"add-line\">+ Add another part</button></section><div class=\"form-actions\"><a href=\"{% url 'orders' %}\">Cancel</a><button type=\"submit\">Submit order</button></div></form><script src=\"{% static 'order.js' %}\" defer></script><script src=\"{% static 'store_lookup.js' %}\" defer></script>{% endblock %}\n"
  },
  "templates/order_detail.html": {
    "previous": [
      "af6e7fd332483dab4f026f3b935a01c8c895ec5b6113269735327c18d3b1b145"
    ],
    "sha256": "32fbfad12cb1cf09852b74b6e3ede9fbdf57dbf32cce9029188b4b0ce88b9a5a",
    "text": "{% extends 'base.html' %}{% block content %}<div class=\"page-title\"><div><p class=\"eyebrow\">STORE #{{ order.store }} \u00b7 {{ order.priority }}</p><h1>{{ order.number }}</h1><p>Requested ship date: {{ order.requested_ship_date|default:'Not specified' }} \u00b7 {{ order.reference }}</p></div><span class=\"badge\">{{ order.get_status_display }}</span></div><section class=\"panel\"><h2>Ship to</h2><p>{{ order.recipient }}<br>{{ order.address }}<br>{{ order.city }}, {{ order.state }} {{ order.postal_code }}</p>{% if order.shipping_county or order.shipping_location_type %}<p>{{ order.shipping_county }}{% if order.shipping_county and order.shipping_location_type %} \u00b7 {% endif %}{{ order.shipping_location_type }}</p>{% endif %}<p>{{ order.notes }}</p><a href=\"{% url 'packing_slip' order.pk %}\">Print pick / packing record</a></section>\n<section class=\"panel\"><h2>Order lines</h2><p>Customer order quantities are in EA. Reserved = allocated in bins; staged = picked but not shipped. Total allocated is reserved plus staged.</p><p>Staged stock has been picked but has not shipped. Backorders are quantities not yet allocated.</p><div class=\"table-wrap\"><table><thead><tr><th>Part</th><th>Requested packs</th><th>Total base quantity</th><th>Reserved</th><th>Backordered</th><th>Picked</th><th>Packed</th><th>Shipped</th><th>Staged</th><th>Returned</th><th>Cancelled</th></tr></thead><tbody>{% for l in lines %}<tr><td>{{ l.part.sku }}<small>{{ l.part.description }}</small></td><td>{{ l.requested_display }}</td><td>{{ l.quantity }} {{ l.base_unit|default:'unverified units' }}</td><td>{{ l.reserved_quantity }}</td><td>{{ l.backordered }}</td><td>{{ l.picked }}</td><td>{{ l.packed }}</td><td>{{ l.shipped }}</td><td>{{ l.staged }}</td><td>{{ l.returned }}</td><td>{{ l.cancelled }}</td></tr>{% endfor %}</tbody></table></div></section>\n{% if is_warehouse %}{% if order.status != 'CANCELLED' and order.status != 'SHIPPED' %}\n<section class=\"panel\"><h2>Backorder priority</h2><form method=\"post\" action=\"{% url 'order_priority' order.pk %}\">{% csrf_token %}<label>Priority<select name=\"priority\"><option value=\"NORMAL\" {% if order.priority == 'NORMAL' %}selected{% endif %}>Normal \u2014 oldest first</option><option value=\"URGENT\" {% if order.priority == 'URGENT' %}selected{% endif %}>Urgent \u2014 before normal orders</option></select></label><label>Reason<input name=\"note\" maxlength=\"500\" required></label><button>Save priority</button></form><h3>Receipt releases</h3>{% for release in order.pick_releases.all %}<p><a href=\"{% url 'release_detail' release.pk %}\">{{ release.number }}</a> \u00b7 {{ release.created_at }}</p>{% empty %}<p>No backorder releases yet.</p>{% endfor %}</section><section class=\"panel\"><h2>Allocate & pick</h2><form method=\"post\" action=\"{% url 'order_action' order.pk %}\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><button name=\"action\" value=\"allocate\">Allocate available stock</button> <button name=\"action\" value=\"pick\">Confirm all reserved stock picked</button> <button class=\"secondary\" name=\"action\" value=\"cancel\">Cancel unpicked order</button></form>\n{% for l in lines %}<h3>{{ l.part.sku }}</h3><p>Order pack: {{ l.case_pack_snapshot|default_if_none:'not configured' }} EA / case; {{ l.pallet_cases_snapshot|default_if_none:'not configured' }} cases / pallet.</p>{% for a in l.allocations.all %}<p>{{ a.stock.location.code }} \u00b7 {{ a.quantity }} \u00b7 {{ a.get_state_display }}{% if a.state == 'RESERVED' and a.stock.kind == 'OVERSTOCK' %} \u2014 replenish to pick location{% endif %}</p>{% endfor %}<form method=\"post\" action=\"{% url 'order_action' order.pk %}\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><input type=\"hidden\" name=\"line\" value=\"{{ l.pk }}\">{% if l.base_unit == 'EA' %}{% include 'unit_select.html' %}{% else %}{% include 'unit_select.html' with legacy=True %}{% endif %}<label>Quantity physically picked<input type=\"number\" name=\"amount\" min=\"0.001\" step=\"0.001\" required></label><button name=\"action\" value=\"pick\">Confirm partial pick</button></form>{% endfor %}</section>\n<section class=\"panel\"><h2>Verify packing</h2><p>Scan the item barcode or enter its exact part number, then choose the unit and confirm the quantity physically packed. The scan identifies the item; the selected unit determines the conversion.</p>{% for l in lines %}<form method=\"post\" action=\"{% url 'order_action' order.pk %}\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><input type=\"hidden\" name=\"line\" value=\"{{ l.pk }}\">{% if l.base_unit == 'EA' %}{% include 'unit_select.html' %}{% else %}{% include 'unit_select.html' with legacy=True %}{% endif %}<h3>{{ l.part.sku }}</h3><p>Order pack: {{ l.case_pack_snapshot|default_if_none:'not configured' }} EA / case; {{ l.pallet_cases_snapshot|default_if_none:'not configured' }} cases / pallet.</p><div class=\"form-grid\"><label>Scan barcode / part<input name=\"scan\" required autocomplete=\"off\"></label><label>Quantity packed<input name=\"amount\" type=\"number\" min=\"0.001\" step=\"0.001\" required></label></div><button name=\"action\" value=\"pack\">Verify packing</button></form>{% endfor %}</section>\n<section class=\"panel\"><h2>Ship verified quantities</h2><p>Ships all packed, unshipped quantities. Any remaining order quantity stays open.</p><form method=\"post\" action=\"{% url 'order_action' order.pk %}\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><div class=\"form-grid\"><label>Carrier<input name=\"carrier\" maxlength=\"100\" required></label><label>Tracking / PRO<input name=\"tracking\" maxlength=\"150\" required></label></div><button name=\"action\" value=\"ship\">Confirm shipment</button></form></section>\n<section class=\"panel\"><h2>Corrections</h2><p>Physically unpack or return stock to its original pick bin before recording a reversal. Shipped stock must use the returns process.</p><form method=\"post\" action=\"{% url 'order_action' order.pk %}\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><label>Line<select name=\"line\">{% for l in lines %}<option value=\"{{ l.pk }}\">{{ l.part.sku }}</option>{% endfor %}</select></label>{% include 'unit_select.html' with legacy=True %}<label>Quantity (for unpack / unpick)<input name=\"amount\" type=\"number\" min=\"0.001\" step=\"0.001\"></label><label>Reason<input name=\"note\" required maxlength=\"500\"></label><button name=\"action\" value=\"unpack\">Reverse packing</button> <button name=\"action\" value=\"unpick\">Return picked quantity to bin</button> <button class=\"secondary\" name=\"action\" value=\"cancel_remaining\">Cancel all unpicked remainder</button></form></section>{% endif %}<section class=\"panel\"><h2>Receive a return</h2><p>Returns go to a held quarantine bin for inspection. Create one in Inventory if needed.</p>{% for l in lines %}{% if l.shipped > l.returned %}<form method=\"post\" action=\"{% url 'return_stock' l.pk %}\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><h3>{{ l.part.sku }}</h3><p>Order pack: {{ l.case_pack_snapshot|default_if_none:'not configured' }} EA / case; {{ l.pallet_cases_snapshot|default_if_none:'not configured' }} cases / pallet.</p><label>Quarantine bin<select name=\"stock\" required>{% for s in return_bins %}{% if s.part_id == l.part_id %}<option value=\"{{ s.pk }}\">{{ s.location.code }}</option>{% endif %}{% endfor %}</select></label>{% if l.base_unit == 'EA' %}{% include 'unit_select.html' %}{% else %}{% include 'unit_select.html' with legacy=True %}{% endif %}<label>Returned quantity<input name=\"amount\" type=\"number\" min=\"0.001\" step=\"0.001\" required></label><label>Reason / reference<input name=\"note\" maxlength=\"500\" required></label><button>Receive return</button></form>{% endif %}{% endfor %}</section>{% endif %}\n<section class=\"panel\"><h2>Shipments</h2>{% for s in shipments %}<p>{{ s.created_at }} \u00b7 {{ s.carrier }} \u00b7 {{ s.tracking }}</p>{% empty %}<p>No shipment records.</p>{% endfor %}</section><section class=\"panel\"><h2>History</h2>{% for e in events %}<div class=\"timeline\"><span>{{ e.at }}</span><strong>{{ e.action }}</strong><small>{{ e.actor }} \u00b7 {{ e.note }}</small></div>{% endfor %}</section>{% endblock %}\n"
  },
  "templates/order_upload.html": {
    "previous": [
      null
    ],
    "sha256": "ee46cabfd53f2868c46b310db5adbef855ddce076f0c553fe172d05df7ec54f7",
    "text": "{% extends 'base.html' %}{% block content %}<h1>Upload store orders</h1><section class=\"panel\"><p><a href=\"{% url 'order_upload_template' %}\">Download Excel-compatible template</a>. Keep the column names: Store Number, Part Number, Quantity EA, Order Reference. Save as XLSX or CSV. Use text format for store and part numbers to preserve leading zeros.</p><p>One row per item. Different stores become separate orders. Different references for the same store become separate orders; repeated items in one store/reference group are combined. Quantities are whole EA only. The store directory supplies the delivery address.</p><p>Up to 2,000 rows / 200 orders per file. You will review the orders before submitting. Available stock is allocated on confirmation; shortages stay backordered.</p><form method=\"post\" enctype=\"multipart/form-data\">{% csrf_token %}{{ form.as_p }}<button>Preview orders</button></form></section>{% endblock %}\n"
  },
  "templates/order_upload_preview.html": {
    "previous": [
      null
    ],
    "sha256": "1e89f70e7e9905ec94a3a369b02c5d85e9f774ed9ba2a634b3ffd4e4d5e95fd1",
    "text": "{% extends 'base.html' %}{% block content %}<h1>Order upload review</h1><p>{{ batch.filename }} \u00b7 {{ batch.preview|length }} store orders</p>{% if batch.submitted_at %}<section class=\"panel\"><h2>Submitted {{ batch.submitted_at }}</h2>{% for order in orders %}<p><a href=\"{% url 'order_detail' order.pk %}\">{{ order.number }}</a> \u00b7 Store {{ order.store }} \u00b7 {{ order.reference }}</p>{% endfor %}</section>{% else %}<p>No stock has been allocated yet. Check each destination and quantity, then confirm the whole file.</p>{% endif %}\n{% for group in batch.preview %}<section class=\"panel\"><h2>Store {{ group.details.store }} \u00b7 {{ group.reference }}</h2><p>{{ group.details.recipient }}<br>{{ group.details.address }}<br>{{ group.details.city }}, {{ group.details.state }} {{ group.details.postal_code }}</p><table><tr><th>Part</th><th>EA</th></tr>{% for sku,qty in group.items.items %}<tr><td>{{ sku }}</td><td>{{ qty }}</td></tr>{% endfor %}</table></section>{% endfor %}\n{% if not batch.submitted_at %}<form method=\"post\">{% csrf_token %}<a href=\"{% url 'order_upload' %}\">Choose another file</a> <button>Confirm and submit all orders</button></form>{% endif %}{% endblock %}\n"
  },
  "templates/packing_slip.html": {
    "previous": [
      "858764427c235066d0b363dbba456de072b18e24d179390523acc56941064ef3",
      "6cd9d79979cb558d6abcf55cbd3e615b42b65c1553b85b2032fedf48d4c64d7e"
    ],
    "sha256": "b0eebb05227b79550fd1f37e9d08b7e7bd66b69274c9d9aa3cda3a1e0f9368d7",
    "text": "{% load static %}<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><title>{{ order.number }} \u00b7 S3PL</title><style>body{font:15px Helvetica,Arial,sans-serif;margin:35px;color:#272525}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{padding:10px;border-bottom:1px solid #ccc;text-align:left}small{display:block}h1{font-size:24px;color:#023171}.print-brand{display:flex;align-items:center;gap:14px;border-bottom:2px solid #023171;padding-bottom:12px;margin:16px 0}.print-brand img{width:64px;height:64px}.print-brand strong{font-size:20px}@media print{a{display:none}}</style></head><body><a href=\"{% url 'order_detail' order.pk %}\">Back to order</a><header class=\"print-brand\"><img src=\"{% static 'brand/s3pl-logo.png' %}\" alt=\"S3PL\"><strong>Superior 3rd Party Logistics</strong></header><h1>S3PL \u00b7 Family Dollar \u00b7 {{ order.number }}</h1><p>{{ order.recipient }} \u00b7 Store {{ order.store }}<br>{{ order.address }}<br>{{ order.city }}, {{ order.state }} {{ order.postal_code }}</p>{% if order.shipping_county or order.shipping_location_type %}<p>{{ order.shipping_county }}{% if order.shipping_county and order.shipping_location_type %} \u00b7 {% endif %}{{ order.shipping_location_type }}</p>{% endif %}<p>Reference: {{ order.reference }} \u00b7 {{ order.get_status_display }}</p><h2>Order / pick record</h2><table><tr><th>Part / unit</th><th>Requested</th><th>Reserved bins</th><th>Packed</th><th>Shipped</th><th>Backordered</th></tr>{% for l in lines %}<tr><td>{{ l.part.sku }} / {{ l.base_unit|default:'Unverified' }}<small>{{ l.part.description }}</small></td><td>{{ l.requested_display }}<small>{{ l.quantity }} {{ l.base_unit|default:'recorded base units' }} total</small></td><td>{% for a in l.allocations.all %}{% if a.state == 'RESERVED' %}{{ a.stock.location.code }}: {{ a.quantity }}<br>{% endif %}{% endfor %}</td><td>{{ l.packed }}</td><td>{{ l.shipped }}</td><td>{{ l.backordered }}</td></tr>{% endfor %}</table><h2>Shipment packing records</h2>{% for s in shipments %}<h3>{{ s.carrier }} \u00b7 {{ s.tracking }}</h3><p>{{ s.created_at }}</p><table><tr><th>Part</th><th>Quantity in this shipment</th></tr>{% for sl in s.lines.all %}<tr><td>{{ sl.line.part.sku }}</td><td>{{ sl.quantity }} {{ sl.line.base_unit|default:'recorded base units' }}</td></tr>{% endfor %}</table>{% empty %}<p>No shipments recorded. This is not proof of shipment.</p>{% endfor %}</body></html>\n"
  },
  "templates/pick_release.html": {
    "previous": [
      null
    ],
    "sha256": "c19e45600eefe77872f806c7dd171c983837fcc657d046d239012efcc78e3b59",
    "text": "{% extends 'base.html' %}{% block content %}\n<div class=\"page-title\"><div><p class=\"eyebrow\">BACKORDER PICK RELEASE</p><h1>{{ release.number }}</h1><p>{{ release.created_at }} \u00b7 {{ release.reason }}</p></div><a href=\"{% url 'order_detail' release.order_id %}\">Open original order</a></div>\n<section class=\"panel\"><h2>{{ release.order.number }} \u00b7 Store {{ release.order.store }}</h2><p>{{ release.order.recipient }}<br>{{ release.order.address }}<br>{{ release.order.city }}, {{ release.order.state }} {{ release.order.postal_code }}</p>{% if release.receipt %}<p>Source receipt: <a href=\"{% url 'receipt_detail' release.receipt_id %}\">{{ release.receipt.number }}</a></p>{% endif %}<p>Pick only rows marked Reserved. Rows already picked or released are shown for reference. Overstock must be replenished to a pick location first. Confirm picking, packing and shipping on the original order.</p><p>Use your browser\u2019s Print command for this release.</p></section>\n<section class=\"panel table-wrap\"><table><tr><th>Part / description</th><th>Current location</th><th>EA</th><th>Status</th></tr>{% for a in allocations %}<tr><td>{{ a.line.part.sku }}<small>{{ a.line.part.description }}</small></td><td>{{ a.stock.location.code }}{% if a.stock.kind == 'OVERSTOCK' %}<small>Replenish before picking</small>{% endif %}</td><td>{{ a.quantity|floatformat:'-3' }}</td><td>{{ a.get_state_display }}</td></tr>{% empty %}<tr><td>No current allocations.</td></tr>{% endfor %}</table></section>\n<details class=\"panel\"><summary>Original release audit snapshot</summary>{% for row in release.snapshot %}<p>{{ row.sku }} \u00b7 {{ row.quantity }} EA \u00b7 {{ row.location }}</p>{% endfor %}</details>{% endblock %}\n"
  },
  "templates/po_detail.html": {
    "previous": [
      null
    ],
    "sha256": "50bfe494267e4e0fe70aedd9892b2214c4438f3172b20dcd1cbc043f4943d1df",
    "text": "{% extends 'base.html' %}{% block content %}<h1>PO {{ po.number }}</h1><p>{{ po.vendor }} \u00b7 {{ percent|floatformat:1 }}% fulfilled \u00b7 {% if complete %}Received in full \u2014 closed{% else %}Open{% endif %}</p><p>Each item must reach its expected quantity. Excess receipts on one item never cover a shortage on another.</p>\n<section class=\"panel table-wrap\"><table><tr><th>Part</th><th>Expected EA</th><th>Accepted EA</th><th>Remaining</th><th>Overreceived</th></tr>{% for r in rows %}<tr><td>{{ r.line.part.sku }}<small>{{ r.line.part.description }}</small></td><td>{{ r.line.expected_quantity }}<details><summary>Correct expected quantity</summary><form method=\"post\">{% csrf_token %}<input type=\"hidden\" name=\"line\" value=\"{{ r.line.pk }}\"><label>Expected EA<input name=\"expected\" type=\"number\" min=\"1\" step=\"1\" value=\"{{ r.line.expected_quantity|floatformat:0 }}\" required></label><label>Reason<input name=\"note\" maxlength=\"500\" required></label><button>Save audited correction</button></form></details></td><td>{{ r.accepted }}</td><td>{{ r.remaining }}</td><td>{{ r.over }}</td></tr>{% endfor %}</table></section>\n{% if unmatched %}<section class=\"panel\"><h2>Unexpected items \u2014 review</h2>{% for sku,qty in unmatched %}<p>{{ sku }} \u00b7 {{ qty }} accepted EA, with no expected line on this PO.</p>{% endfor %}</section>{% endif %}\n<section class=\"panel\"><h2>Receipts for this PO</h2>{% for receipt in receipts %}<p><a href=\"{% url 'receipt_detail' receipt.pk %}\">{{ receipt.number }}</a> \u00b7 {{ receipt.supplier }} \u00b7 {{ receipt.received_date }} \u00b7 {{ receipt.get_status_display }}</p>{% empty %}<p>No matching receipts.</p>{% endfor %}</section>{% endblock %}\n"
  },
  "templates/purchase_orders.html": {
    "previous": [
      null
    ],
    "sha256": "e0815ac9d043eb6543e19e0aaa17c97f8605c3ec54cdcdbf21e7ea5a6783b63c",
    "text": "{% extends 'base.html' %}{% block content %}<h1>Purchase orders</h1><p>Only accepted received quantities count toward PO completion. A PO closes automatically when every expected item is fulfilled.</p>\n<form class=\"filters\"><input name=\"q\" value=\"{{ q }}\" placeholder=\"Search PO number or vendor\"><button>Search</button></form>\n<section class=\"panel table-wrap\"><table><tr><th>PO</th><th>Vendor</th><th>Fulfilled</th><th>Status</th></tr>{% for r in rows %}<tr><td><a href=\"{% url 'po_detail' r.po.pk %}\">{{ r.po.number }}</a></td><td>{{ r.po.vendor }}</td><td>{{ r.percent|floatformat:1 }}%</td><td>{% if r.complete %}Received in full \u2014 closed{% else %}Open{% endif %}</td></tr>{% empty %}<tr><td>No matching purchase orders.</td></tr>{% endfor %}</table></section>{% include 'pagination.html' %}\n<section class=\"panel\"><h2>Import expected quantities</h2><p><a href=\"{% url 'po_template' %}\">Download Excel-compatible CSV template</a>. Keep these four column headers: PO Number, Vendor, Part Number, Expected EA. One row per PO/item. Save as XLSX or CSV. Store PO and part numbers as text to keep leading zeros.</p><p>Identical reports do not add duplicates. Existing quantities cannot be silently overwritten; use the PO detail correction form. Items omitted from a later report stay on the PO. Historical receipts with this exact PO number are included automatically.</p><form method=\"post\" enctype=\"multipart/form-data\">{% csrf_token %}{{ form.as_p }}<button>Import PO report</button></form></section>{% endblock %}\n"
  },
  "templates/receipt_detail.html": {
    "previous": [
      "4549f1a32df61ed3aee7e9590d9e42cd2006b363b4f1fa1033ddd91de1a337e5"
    ],
    "sha256": "e2a87f20dbb59ee1aca5a24431504cafe0ed127f55a601119e07d0de272e76d9",
    "text": "{% extends 'base.html' %}{% block content %}\n<div class=\"page-title\"><div><p class=\"eyebrow\">POSTED RECEIPT</p><h1>Receiving confirmation</h1><p class=\"receipt-number\">{{ receipt.number }}</p></div><a href=\"{% url 'receipts' %}\">Receipt queue</a></div>\n<section class=\"panel\"><h2>{{ receipt.supplier }}</h2><p>Received: {{ receipt.received_date }}<br>PO: {{ receipt.po_number|default:'Not supplied' }}<br>BOL / delivery reference: {{ receipt.reference }}<br>Posted by {{ receipt.posted_by }} at {{ receipt.posted_at }}</p><p>{{ receipt.notes|linebreaksbr }}</p><details><summary>Add / correct PO reference</summary><form method=\"post\" action=\"{% url 'receipt_po' receipt.pk %}\">{% csrf_token %}<p>This updates the delivery PO and rows matching its prior value. Rows with another PO override remain unchanged.</p><label>PO number<input name=\"po_number\" value=\"{{ receipt.po_number }}\" maxlength=\"100\"></label><label>Reason<input name=\"note\" maxlength=\"500\" required></label><button>Save audited PO reference</button></form></details><p>This receipt is locked after posting. Corrections must be recorded in the inventory history with the receipt number and reason.</p></section>\n<section class=\"panel table-wrap\"><h2>Received inventory</h2><table><thead><tr><th>Part</th><th>Entered quantity</th><th>Case pack</th><th>Total eaches</th><th>Putaway location</th><th>Condition</th><th>Accepted EA toward PO</th></tr></thead><tbody>{% for l in lines %}<tr><td>{{ l.sku }}<small>{{ l.description }}</small><small>PO: {{ l.po_number|default:'Not supplied' }}</small><small>{{ l.note }}</small></td><td>{{ l.entry.quantity }} {{ l.entry.unit }} + {{ l.entry.loose_eaches }} loose EA</td><td>{{ l.entry.case_pack|default_if_none:'\u2014' }} EA / case<br>{{ l.entry.pallet_cases|default_if_none:'\u2014' }} cases / pallet</td><td>{{ l.quantity }}</td><td>{{ l.location }}</td><td>{% if l.held %}On hold{% else %}Received{% endif %}</td><td>{{ l.accepted_quantity }}<details><summary>Record inspection / correction</summary><form method=\"post\" action=\"{% url 'receipt_accepted' l.pk %}\">{% csrf_token %}<label>Line PO number<input name=\"po_number\" value=\"{{ l.po_number }}\" maxlength=\"100\"></label><label>Total accepted EA<input type=\"number\" name=\"accepted\" value=\"{{ l.accepted_quantity|floatformat:0 }}\" min=\"0\" max=\"{{ l.quantity|floatformat:0 }}\" step=\"1\" required></label><label>Reason<input name=\"note\" maxlength=\"500\" required></label><p>Updates PO acceptance only. Inventory corrections use Count / hold.</p><button>Save acceptance</button></form></details></td></tr>{% endfor %}</tbody></table></section>\n<section class=\"panel\"><h2>Backorder pick releases</h2>{% for release in receipt.pick_releases.all %}<p><a href=\"{% url 'release_detail' release.pk %}\">{{ release.number }}</a> \u00b7 {{ release.order.number }} \u00b7 Store {{ release.order.store }}</p>{% empty %}<p>No backorders released by this receipt.</p>{% endfor %}</section><section class=\"panel\"><h2>Customer email \u00b7 {{ email.get_status_display }}</h2><p>Send to: {{ email.group_name }} \u2014 {{ email.recipients|join:', ' }}<br>Sent: {{ email.sent_at|default:'Not confirmed' }}</p><p>Documents selected: {{ email.document_names|join:', '|default:'None' }}</p><details><summary>Preview receipt email</summary><pre class=\"email-preview\">{{ email.body }}</pre></details>\n{% if not email_enabled %}<p>Email delivery is disabled. IT must configure the sender and enable receipt emails first.</p>{% endif %}\n{% if email.status != 'SENT' %}<form method=\"post\" action=\"{% url 'receipt_email_action' receipt.pk %}\">{% csrf_token %}{% if email.status == 'FAILED' or email.status == 'SENDING' %}<label><input type=\"checkbox\" name=\"checked_delivery\" required>I checked the sender/mailbox and confirmed the prior attempt was not delivered.</label><p class=\"muted\">A connection failure can happen after the provider accepted a message. Check before retrying. A running send cannot be retried for five minutes.</p>{% endif %}<button>{% if email.status == 'PENDING' %}Send pending email{% else %}Retry email only{% endif %}</button><small>This action never posts inventory again.</small></form>{% endif %}\n{% for a in email.attempts.all %}<p class=\"muted\">{{ a.started_at }} \u00b7 {{ a.status }}{% if a.error %} \u00b7 {{ a.error }}{% endif %}</p>{% endfor %}<small>Sent means the email provider accepted the message; it does not confirm the recipient opened it.</small></section>\n<section class=\"panel\"><h2>Receipt documents</h2>{% for d in documents %}<p><a href=\"{% url 'receipt_document' d.pk %}\" target=\"_blank\" rel=\"noopener\">{{ d.filename }}</a> \u00b7 {{ d.size|filesizeformat }} \u00b7 <a href=\"{% url 'receipt_document' d.pk %}?download=1\">Download</a></p>{% empty %}<p>No documents attached.</p>{% endfor %}</section><section class=\"panel\"><h2>Receipt audit history</h2>{% for event in receipt.event_set.all %}<p>{{ event.at }} \u00b7 {{ event.actor }} \u00b7 {{ event.action }}<br>{{ event.note }}{% if event.before is not None %}<br>{{ event.before }} \u2192 {{ event.after }}{% endif %}</p>{% endfor %}</section>{% endblock %}\n"
  },
  "templates/receipt_edit.html": {
    "previous": [
      "d18054c9e6ff44a0b0b3d2b6e8c40dba48e9216b741d6ac32059e8f9d2a8f1e9"
    ],
    "sha256": "77a5b6430005124fda7b91a994280f5283458cb10c947419973f0849175349f0",
    "text": "{% extends 'base.html' %}{% load static %}{% block content %}\n<div class=\"page-title\"><div><p class=\"eyebrow\">OFFICE RECEIVING</p><h1>{% if receipt %}Edit receipt{% else %}New Receipt{% endif %}</h1><p>Enter the floor\u2019s putaway sheet, attach the scans, then submit.</p></div><a href=\"{% url 'receipts' %}\">Receipt queue</a></div>\n{% if receipt %}<p class=\"receipt-number\">{{ receipt.number }} \u00b7 {{ receipt.get_status_display }}</p>{% endif %}\n{% if error %}<div class=\"notice error\">{{ error }}</div>{% endif %}\n{% if not email_enabled %}<div class=\"notice\">Customer email is disabled until IT configures the sender and enables receipt emails. Posted receipts keep their email pending.</div>{% endif %}\n<form method=\"post\" enctype=\"multipart/form-data\" id=\"receipt-form\">{% csrf_token %}<input type=\"hidden\" name=\"request_key\" value=\"{{ request_key }}\"><input type=\"hidden\" name=\"revision\" value=\"{{ receipt.revision|default:'0' }}\">\n<section class=\"panel\"><h2>Delivery details</h2>{{ form.non_field_errors }}<div class=\"form-grid\">{% for field in form %}<div><label for=\"{{ field.id_for_label }}\">{{ field.label }}</label>{{ field }}{{ field.errors }}</div>{% endfor %}</div><small>The saved group contains the approved FD recipients. An administrator configures its addresses before a receipt can be submitted.</small></section>\n<section class=\"panel\"><h2>What was received and put away</h2><p>Enter actual received quantities. For a delivery containing several POs, enter a PO override on each affected row; the delivery still sends one email. Use separate rows for split locations or loose eaches. Damaged quantities belong in a held quarantine bin. Record shortages in the notes.</p><datalist id=\"receipt-parts\">{% for p in catalog %}<option value=\"{{ p.sku }}\">{{ p.description }}</option>{% endfor %}</datalist><datalist id=\"receipt-locations\">{% for b in bins %}<option value=\"{{ b.location }}\">{{ b.sku }}{% if b.held %} \u00b7 ON HOLD{% endif %}</option>{% endfor %}</datalist>\n<div class=\"table-wrap\"><table class=\"receipt-grid\"><tbody id=\"receipt-rows\">{% for row in rows %}{% include 'receipt_row.html' %}{% endfor %}</tbody></table></div><button type=\"button\" class=\"secondary\" id=\"add-receipt-row\">+ Add item / location</button><p class=\"muted\">Unknown balances must be counted first. New part/location combinations can be set up in Inventory \u2192 Add a part / bin.</p></section>\n<section class=\"panel\"><h2>BOL, packing list and photos</h2><p>PDF, JPG or PNG. Up to 6 MB per file and 12 MB per delivery. Choose which documents accompany the email.</p>\n{% for d in documents %}<div class=\"document-card\"><a href=\"{% url 'receipt_document' d.pk %}\" target=\"_blank\" rel=\"noopener\">Preview {{ d.filename }}</a> <small>{{ d.size|filesizeformat }}</small><label><input type=\"checkbox\" name=\"keep_docs\" value=\"{{ d.pk }}\" checked>Keep document (uncheck to remove on save)</label><label><input type=\"checkbox\" name=\"email_docs\" value=\"{{ d.pk }}\" {% if d.include_in_email %}checked{% endif %}>Include in customer email</label></div>{% endfor %}\n<div id=\"upload-zone\" class=\"upload-zone\"><label for=\"receipt-files\">Drag scanned documents here, or choose files</label><input id=\"receipt-files\" name=\"documents\" type=\"file\" accept=\".pdf,.jpg,.jpeg,.png\" multiple></div><p id=\"upload-error\" role=\"alert\"></p><div id=\"new-documents\"></div></section>\n<p>Submit Receipt confirms the paperwork and posts inventory. Save Draft leaves inventory unchanged.</p><div class=\"form-actions\"><button class=\"secondary\" name=\"action\" value=\"clarify\">Needs clarification</button><button class=\"secondary\" name=\"action\" value=\"draft\">Save Draft</button><button name=\"action\" value=\"submit\">Submit Receipt</button></div></form>\n<template id=\"empty-receipt-row\">{% include 'receipt_row.html' with row=None %}</template>{{ catalog|json_script:'receipt-catalog' }}{{ bins|json_script:'receipt-bins' }}<script src=\"{% static 'receiving.js' %}\" defer></script>{% endblock %}\n"
  },
  "templates/receipt_row.html": {
    "previous": [
      "f9374194190c751963d7300b1223a1322da7e20a7757646407d94b80c14d8498"
    ],
    "sha256": "c7b7f590213d01da2623bbd6316abdb218fdda3c215e6e67d4b4e75978dbb8e8",
    "text": "<tr class=\"receipt-row\"><td><label>Part number<input name=\"sku\" value=\"{{ row.sku }}\" list=\"receipt-parts\" maxlength=\"100\" autocomplete=\"off\"></label><small class=\"part-description\"></small></td>\n<td><label>Putaway location<input name=\"location\" value=\"{{ row.location }}\" list=\"receipt-locations\" maxlength=\"100\"></label><small class=\"bin-state\"></small></td>\n<td><label>Quantity<input name=\"quantity\" value=\"{{ row.quantity }}\" type=\"number\" min=\"0\" step=\"1\"></label><label>Unit<select name=\"unit\"><option value=\"EA\">Eaches</option><option value=\"CASE\" {% if row.unit == 'CASE' %}selected{% endif %}>Cases</option><option value=\"PALLET\" {% if row.unit == 'PALLET' %}selected{% endif %}>Pallets</option></select></label></td>\n<td><label>Loose eaches<input name=\"loose_eaches\" value=\"{{ row.loose_eaches|default:'0' }}\" type=\"number\" min=\"0\" step=\"1\"></label><small class=\"pack-info\"></small><input type=\"hidden\" name=\"case_pack\" value=\"{{ row.case_pack }}\"><input type=\"hidden\" name=\"pallet_cases\" value=\"{{ row.pallet_cases }}\"><button type=\"button\" class=\"secondary refresh-pack\" hidden>Use current pack</button></td>\n<td><strong class=\"each-total\">\u2014</strong><small>Total eaches</small><label>Condition<select name=\"damaged\"><option value=\"0\">Good</option><option value=\"1\" {% if row.damaged %}selected{% endif %}>Damaged / hold</option></select></label></td>\n<td><label>PO override (optional)<input name=\"line_po\" value=\"{{ row.line_po }}\" maxlength=\"100\" placeholder=\"Use delivery PO\"></label><label>Line note<input name=\"note\" value=\"{{ row.note }}\" maxlength=\"500\"></label><button type=\"button\" class=\"secondary remove-receipt-row\">Remove row</button></td></tr>\n"
  },
  "templates/receipts.html": {
    "previous": [
