    "sha256": "5a17eff2602f8e09b9fa52d16cabab4c4d154910a5fd0051f522d0f7ed845573",
    "text": "{% extends 'base.html' %}{% block content %}\n<div class=\"page-title\"><div><p class=\"eyebrow\">OFFICE RECEIVING</p><h1>Receipts</h1><p>One delivery, one receipt, one customer email.</p></div><a class=\"button\" href=\"{% url 'receipt_new' %}\">+ New Receipt</a></div>\n<form class=\"filters\" method=\"get\"><input name=\"q\" value=\"{{ q }}\" placeholder=\"Search vendor, PO, BOL, receipt or part\"><input name=\"vendor\" value=\"{{ vendor }}\" placeholder=\"Filter vendor\"><input name=\"po\" value=\"{{ po }}\" placeholder=\"Exact PO number\"><select name=\"status\"><option value=\"\">All receipts</option><option value=\"DRAFT\" {% if status == 'DRAFT' %}selected{% endif %}>Drafts</option><option value=\"CLARIFY\" {% if status == 'CLARIFY' %}selected{% endif %}>Needs clarification</option><option value=\"POSTED\" {% if status == 'POSTED' %}selected{% endif %}>Posted</option></select><button>Search</button></form>\n<section class=\"panel table-wrap\"><table><thead><tr><th>Receipt / reference</th><th>Supplier</th><th>Received</th><th>Inventory</th><th>Customer email</th></tr></thead><tbody>{% for r in page %}<tr><td><a href=\"{% url 'receipt_detail' r.pk %}\" class=\"receipt-number\">{{ r.number }}</a><small>BOL: {{ r.reference }}</small><small>PO: {{ r.po_number|default:'Not supplied' }}</small></td><td>{{ r.supplier|default:'Not entered' }}</td><td>{{ r.received_date|default:'Not entered' }}</td><td>{{ r.get_status_display }}</td><td>{% if r.status == 'POSTED' %}{{ r.email.get_status_display }}{% else %}Not sent{% endif %}</td></tr>{% empty %}<tr><td colspan=\"5\">No receipts yet. Select New Receipt to enter the floor\u2019s putaway sheet.</td></tr>{% endfor %}</tbody></table></section>{% include 'pagination.html' %}{% endblock %}\n"
  },
