    "sha256": "20d663ed449653db7ecd167e01624ab6f93c2a1acde872293b66a0ea6b319658",
    "text": "{% load static %}<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#023171\"><title>Customer Login \u00b7 S3PL</title><link rel=\"stylesheet\" href=\"{% static 'app.css' %}\"><script src=\"{% static 'brand/globe-motion.js' %}\" defer></script><script src=\"{% static 'brand/pallet-wrapper.js' %}\" defer></script></head>\n<body class=\"login-page\"><a class=\"skip-link\" href=\"#login-content\">Skip to sign in</a><div class=\"login-topline\"><span>WAREHOUSING \u00b7 DISTRIBUTION \u00b7 FULFILLMENT</span><span>MIDDLE TENNESSEE</span></div>\n<header class=\"login-header\"><a class=\"brand\" href=\"https://s3pl-company.s3pl-nashvil-8733.chatgpt.site\">{% include 'brand/globe.html' %}<span class=\"brand-copy\"><b class=\"brand-name\">Superior 3rd Party Logistics</b><span class=\"brand-caption\">CUSTOMER OPERATIONS</span></span></a><a class=\"back-link\" href=\"https://s3pl-company.s3pl-nashvil-8733.chatgpt.site\">Back to S3PL <svg viewBox=\"0 0 24 24\" width=\"1em\" height=\"1em\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" style=\"display:inline-block;vertical-align:-.1em;flex:0 0 1em\"><path d=\"M6 18 18 6M6 6h12v12\"/></svg></a></header>\n<main class=\"login-shell\" id=\"login-content\"><section class=\"login-story\"><div><p class=\"eyebrow\">YOUR WAREHOUSE. CONNECTED.</p><h1>Your inventory.<br>Your orders.<br><span>All in one place.</span></h1><p class=\"login-intro\">From the receiving dock to the final shipment.<br> Welcome to your S3PL operations portal.</p></div><div class=\"login-visual\">{% include 'brand/pallet_wrapper.html' %}</div><div class=\"login-proof\"><span>RECEIVE</span><span>MANAGE</span><span>FULFILL</span></div></section>\n<section class=\"login-form\"><div class=\"login-customer\"><span class=\"avatar\" aria-hidden=\"true\">FD</span><div><small>YOUR CUSTOMER PORTAL</small><strong>Family Dollar</strong></div></div><p class=\"eyebrow\">WELCOME BACK</p><h2>Let\u2019s get to work.</h2><p>Sign in to view inventory and manage orders.</p><form method=\"post\">{% csrf_token %}{{ form.as_p }}{% if next %}<input type=\"hidden\" name=\"next\" value=\"{{ next }}\">{% endif %}<button>Sign in <span aria-hidden=\"true\">\u2192</span></button></form><p class=\"login-help\">Need access or a password reset?<br>Contact your S3PL account administrator.</p></section></main><footer class=\"login-footer\"><span>Superior 3rd Party Logistics</span><span>Family Dollar \u00b7 Customer operations</span></footer></body></html>\n"
  },
