    "sha256": "2225d02af215d0337cae319f7b7a1c32b96fc54eaa0c09d37c9d751b68e32e08",
    "text": "<div id=\"store-lookup\" data-search-url=\"{% url 'store_search' %}\">\n  <label for=\"store-search\">Find a Family Dollar store</label>\n  <input type=\"search\" id=\"store-search\" placeholder=\"Store number, ZIP, city or street address\" autocomplete=\"off\" maxlength=\"100\" aria-describedby=\"store-search-status\" aria-controls=\"store-search-results\">\n  <p id=\"store-search-status\" class=\"muted\" role=\"status\" aria-live=\"polite\">Enter at least two characters, then select the correct store.</p>\n  <div id=\"store-search-results\" aria-label=\"Matching stores\" style=\"display:grid;gap:8px;margin-bottom:12px\"></div>\n  <button type=\"button\" class=\"secondary\" id=\"store-manual\">Enter delivery address manually</button>\n  {% if is_warehouse %}<p><a href=\"{% url 'directory_import' %}\">Import or update store directory</a></p>{% endif %}\n  <noscript><p>Store search needs JavaScript. You can enter the delivery address in the fields below.</p></noscript>\n</div>\n"
  },
  "templates/work_queue.html": {
    "previous": [
      "32a4ee665c62dbe7be092bedd3849690a473566314ea3ab06af75d67246250ae"
    ],
    "sha256": "cc6d9c8194f2dcf04c7b341b79136ee47986e9b0587dfd447b176f1dd7c60437",
    "text": "{% extends 'base.html' %}{% block content %}<h1>Warehouse tasks</h1><section class=\"panel\"><h2>Released backorders ready for picking</h2>{% for release in releases %}<p><a href=\"{% url 'release_detail' release.pk %}\">{{ release.number }}</a> \u00b7 {{ release.order.number }} \u00b7 Store {{ release.order.store }} \u00b7 {{ release.created_at }}</p>{% empty %}<p>No released backorders awaiting picking.</p>{% endfor %}</section><section class=\"panel\"><h2>Replenish pick locations</h2><p>Suggestions include allocated overstock and each item\u2019s pick minimum. Confirm the source and destination before moving stock.</p><table><tr><th>Part</th><th>Suggested movement</th><th>Action</th></tr>{% for r in replenishment %}<tr><td>{{ r.part.sku }}</td><td>{{ r.replenish|floatformat:'-3' }} {{ r.part.unit }}</td><td>{% if r.overstock %}<a href=\"{% url 'transfer' r.overstock.pk %}\">Choose transfer</a>{% endif %}</td></tr>{% empty %}<tr><td>Nothing awaiting replenishment.</td></tr>{% endfor %}</table></section>\n<section class=\"panel\"><h2>Backorders awaiting allocation</h2><p>Accepted receipts and hold releases allocate waiting orders automatically: urgent first, then oldest first. Physical picking and shipping still require staff confirmation.</p>{% for r in backorders %}<p>{{ r.part.sku }} \u00b7 {{ r.backordered|floatformat:'-3' }} waiting \u00b7 {{ r.available|floatformat:'-3' }} available</p>{% empty %}<p>No backorders.</p>{% endfor %}<a href=\"{% url 'orders' %}?status=PARTIAL\">Open partial orders \u2192</a></section>\n<section class=\"panel\"><h2>Counts due</h2><p>Imported balances need their first recorded count. Later counts follow each item\u2019s interval.</p><table><tr><th>Part / location</th><th>Last count</th><th>Action</th></tr>{% for s in counts %}<tr><td>{{ s.part.sku }} / {{ s.location.code }}</td><td>{{ s.last_counted_at|default:'Not recorded' }}</td><td><a href=\"{% url 'stock_edit' s.pk %}\">Count</a></td></tr>{% empty %}<tr><td>No counts due.</td></tr>{% endfor %}</table></section>\n<section class=\"panel\"><h2>Quality holds</h2>{% for s in held %}<p><a href=\"{% url 'stock_edit' s.pk %}\">{{ s.part.sku }} / {{ s.location.code }}</a> \u00b7 {{ s.on_hand|default_if_none:'Uncounted' }} \u00b7 {{ s.hold_reason }}</p>{% empty %}<p>No stock on hold.</p>{% endfor %}</section>{% endblock %}\n"
  },
  "warehouse/admin.py": {
    "previous": [
      "fc76f1d23e847226eb1144b8afb15efabd4c6a1ee78cd7e24af58835e6d4d2be"
    ],
    "sha256": "63bc48dbe93d25bc996d3197b722f5527191c06b1992e0ff38f5bd9fe12944f1",
    "text": "from django.contrib import admin\nfrom .models import StoreLocation\nfrom .models import Part,Location,Stock,Order,OrderLine,Allocation,Event\nadmin.site.site_header='S3PL Customer Operations'\nadmin.site.site_title='S3PL WMS'\n\n\n\nclass ReadOnly(admin.ModelAdmin):\n    def has_add_permission(self,request): return False\n    def has_delete_permission(self,request,obj=None): return False\n    def has_change_permission(self,request,obj=None): return False\n\n@admin.register(StoreLocation)\nclass StoreLocationAdmin(ReadOnly):\n    list_display=['store_number','address','city','state','postal_code','county','location_type','active']\n    search_fields=['store_number','postal_code','city','address','county']\n    list_filter=['customer_code','state','active']\n\n@admin.register(Stock)\nclass StockAdmin(ReadOnly):\n    list_display=['part','location','kind','on_hand','reserved','count_required']\n    search_fields=['part__sku','location__code']\n    list_filter=['kind']\n\n@admin.register(Event)\nclass EventAdmin(ReadOnly):\n    list_display=['at','actor','action','stock','quantity','before','after']\n    search_fields=['action','note','receipt__supplier','receipt__po_number','receipt__reference','stock__part__sku','actor__username']\n    list_filter=['action']\n\nadmin.site.register(Order,ReadOnly)\nadmin.site.register(OrderLine,ReadOnly)\nadmin.site.register(Allocation,ReadOnly)\n\nadmin.site.register(Part,ReadOnly)\nadmin.site.register(Location,ReadOnly)\nfrom .models import Shipment,ShipmentLine,ReturnReceipt,AlertSubscription,AlertDelivery,OperationKey\nfor model in [Shipment,ShipmentLine,ReturnReceipt,AlertSubscription,AlertDelivery,OperationKey]: admin.site.register(model,ReadOnly)\n\nfrom .models import ReceiptGroup,InboundReceipt,InboundReceiptLine,ReceiptDocument,ReceiptEmail,ReceiptEmailAttempt\n@admin.register(ReceiptGroup)\nclass ReceiptGroupAdmin(admin.ModelAdmin):\n    list_display=['name','active']\n    def save_model(self,request,obj,form,change):\n        super().save_model(request,obj,form,change)\n        Event.objects.create(actor=request.user,action='RECEIPT_GROUP_SETTINGS',note=f'Group {obj.pk} ({obj.name}) configuration updated.')\n    def has_delete_permission(self,request,obj=None): return False\nfor model in [InboundReceipt,InboundReceiptLine,ReceiptEmail,ReceiptEmailAttempt]: admin.site.register(model,ReadOnly)\n@admin.register(ReceiptDocument)\nclass ReceiptDocumentAdmin(ReadOnly):\n    exclude=['content']\n    list_display=['filename','receipt','size','uploaded_at']\n\nfrom .models import PickRelease,PurchaseOrder,PurchaseOrderLine\nfor model in [PickRelease,PurchaseOrder,PurchaseOrderLine]: admin.site.register(model,ReadOnly)\n"
  },
  "warehouse/backorders.py": {
    "previous": [
      null
    ],
    "sha256": "4998576fa53579471d4912a8ae57b72d0fe3fa4ff8dfee73267f78d32f4e9267",
    "text": "\"\"\"Receipt-triggered releases. Caller locks orders BEFORE parts, in the receipt transaction.\"\"\"\nfrom django.db import transaction\nfrom .models import Order, Part, PickRelease, Event\nfrom .services import reserve_line, WorkflowError\nfrom .operations import require_warehouse, refresh_status\n\n\ndef lock_waiting_orders(part_ids):\n    # A single total lock order avoids deadlocks between overlapping multi-part receipts.\n    ids=Order.objects.filter(lines__part_id__in=part_ids).exclude(status__in=['SHIPPED','CANCELLED']).values('pk')\n    return list(Order.objects.select_for_update().filter(pk__in=ids).order_by('pk'))\n\n\ndef release_waiting(actor, orders, part_ids, receipt=None, reason='Stock released'):\n    releases=[]\n    for order in sorted(orders,key=lambda o:(o.priority!='URGENT',o.created_at,str(o.pk))):\n        if order.status in ('SHIPPED','CANCELLED'): continue\n        allocations=[]\n        for line in order.lines.filter(part_id__in=part_ids).select_related('part').order_by('part_id'):\n            allocations.extend(reserve_line(actor,line) or [])\n        if not allocations: continue\n        snapshot=[dict(sku=a.line.part.sku,location=a.stock.location.code,quantity=str(a.quantity)) for a in allocations]\n        release=PickRelease.objects.create(order=order,receipt=receipt,actor=actor,reason=reason,snapshot=snapshot)\n        for allocation in allocations:\n            allocation.release=release;allocation.save(update_fields=['release'])\n        refresh_status(order)\n        Event.objects.create(actor=actor,order=order,receipt=receipt,action='BACKORDER_RELEASE',\n            quantity=sum(a.quantity for a in allocations),entry={'release':str(release.pk),'items':snapshot},note=release.number)\n        releases.append(release)\n    return releases\n\n\n@transaction.atomic\ndef change_priority(actor, order_id, priority, note):\n    require_warehouse(actor)\n    if priority not in ('NORMAL','URGENT') or not note.strip(): raise WorkflowError('Choose a priority and enter a reason.')\n    order=Order.objects.select_for_update().get(pk=order_id)\n    if order.status in ('SHIPPED','CANCELLED'): raise WorkflowError('This order is closed.')\n    before=order.priority\n    order.priority=priority;order.save(update_fields=['priority'])\n    Event.objects.create(actor=actor,order=order,action='ORDER_PRIORITY',entry={'before':before,'after':priority},note=note.strip()[:500])\n"
  },
  "warehouse/extra_views.py": {
    "previous": [
      "9e23db78de52445341cb59ffb1b3768f032a53f0fa8147434e9e260d3d47daee"
    ],
    "sha256": "e663609263ec554c52262f85a6c04653f0c226dc03d3f24a59f69646b591bd7c",
    "text": "import csv\nimport uuid\nfrom django.contrib import messages\nfrom django.db import transaction\nfrom django.http import HttpResponse\nfrom django.shortcuts import render,redirect,get_object_or_404\nfrom django.views.decorators.http import require_POST\nfrom django.utils import timezone\nfrom .views import access,ctx\nfrom .models import Part,Stock,Location,Event,Order,OrderLine,AlertSubscription\nfrom .forms import PartForm,NewBinForm\nfrom .services import WorkflowError\nfrom .notifications import fd_recipient\nfrom .operations import set_hold,receive_return\nfrom .reporting import stock_summary,due_counts\n\n\n@access()\ndef alerts(request):\n    subscription,_=AlertSubscription.objects.get_or_create(user=request.user)\n    if request.method=='POST':\n        enabled=request.POST.get('enabled')=='on'\n        if enabled and not fd_recipient(request.user):\n            messages.error(request,'Customer stock emails are limited to FD Corporate accounts.')\n        elif enabled and not request.user.email:\n            messages.error(request,'Ask an administrator to add your approved email address first.')\n        else:\n            subscription.enabled=enabled;subscription.save(update_fields=['enabled'])\n            messages.success(request,'Email preference saved. Delivery requires an enabled company email sender and scheduled digest.')\n        return redirect('alerts')\n    rows=stock_summary()\n    return render(request,'alerts.html',ctx(request,rows=[r for r in rows if r['low']],unconfigured=sum(r['part'].low_stock_threshold is None for r in rows),subscription=subscription,is_fd=fd_recipient(request.user)))\n\n\n@access(warehouse=True)\ndef work_queue(request):\n    rows=stock_summary()\n    from .models import PickRelease\n    releases=PickRelease.objects.filter(allocations__state='RESERVED').select_related('order').distinct()\n    return render(request,'work_queue.html',ctx(request,releases=releases,replenishment=[r for r in rows if r['replenish']>0],backorders=[r for r in rows if r['backordered']>0],counts=due_counts(),held=Stock.objects.filter(held=True).select_related('part','location')))\n\n\n@access(warehouse=True)\ndef part_settings(request,pk):\n    if request.method=='POST':\n        with transaction.atomic():\n            part=get_object_or_404(Part.objects.select_for_update(),pk=pk)\n            before={field:getattr(part,field) for field in PartForm.Meta.fields}\n            form=PartForm(request.POST,instance=part)\n            if form.is_valid():\n                part=form.save()\n                changes='; '.join(f'{field}: {before[field]} -> {getattr(part,field)}' for field in PartForm.Meta.fields if before[field]!=getattr(part,field))\n                Event.objects.create(actor=request.user,action='ITEM_SETTINGS',note=f'{part.sku}: {changes}')\n                messages.success(request,'Item pack settings saved. Existing orders retain their original conversion factors.')\n                return redirect('inventory')\n    else:\n        part=get_object_or_404(Part,pk=pk);form=PartForm(instance=part)\n    return render(request,'generic_form.html',ctx(request,title=f'Item settings \u00b7 {part.sku}',form=form))\n\n\n@access(warehouse=True)\ndef new_bin(request):\n    form=NewBinForm(request.POST or None)\n    if request.method=='POST' and form.is_valid():\n        d=form.cleaned_data\n        with transaction.atomic():\n            part,_=Part.objects.get_or_create(sku=d['sku'],defaults={'description':d['description']})\n            part=Part.objects.select_for_update().get(pk=part.pk)\n            location,_=Location.objects.get_or_create(code=d['location'])\n            if part.unit=='EA' and d['opening_count'] is not None and d['opening_count']!=d['opening_count'].to_integral_value(): form.add_error('opening_count','Enter a whole number of eaches.')\n            elif Stock.objects.filter(part=part,location=location).exists(): form.add_error('location','This part already has a record in this location.')\n            else:\n                s=Stock.objects.create(part=part,location=location,kind=d['kind'],on_hand=d['opening_count'],count_required=d['opening_count'] is None,held=d['held'],hold_reason=d['note'] if d['held'] else '',last_counted_at=timezone.now() if d['opening_count'] is not None else None)\n                Event.objects.create(actor=request.user,stock=s,action='BIN_OPENED',quantity=s.on_hand or 0,after=s.on_hand,note=d['note'])\n                return redirect('inventory')\n    return render(request,'generic_form.html',ctx(request,title='Add a part / bin',form=form))\n\n\n@require_POST\n@access(warehouse=True)\ndef hold(request,pk):\n    get_object_or_404(Stock,pk=pk)\n    try: set_hold(request.user,pk,request.POST.get('held')=='1',request.POST.get('note',''))\n    except WorkflowError as e: messages.error(request,str(e))\n    else: messages.success(request,'Stock hold updated.')\n    return redirect('stock_edit',pk=pk)\n\n\n@require_POST\n@access(warehouse=True)\ndef return_stock(request,pk):\n    line=get_object_or_404(OrderLine,pk=pk)\n    try:\n        stock_id=int(request.POST.get('stock',''))\n        get_object_or_404(Stock,pk=stock_id)\n        receive_return(request.user,pk,stock_id,request.POST.get('amount',''),request.POST.get('note',''),uuid.UUID(request.POST.get('request_key','')),unit=request.POST.get('unit','BASE'))\n    except (WorkflowError,ValueError) as e: messages.error(request,str(e))\n    else: messages.success(request,'Return received into quarantine. Inspect before releasing.')\n    return redirect('order_detail',pk=line.order_id)\n\n\ndef safe_cell(value):\n    text=str(value if value is not None else '')\n    return \"'\"+text if text.lstrip().startswith(('=','+','-','@','\\t','\\r','\\n')) else text\n\n\n@access()\ndef inventory_export(request):\n    response=HttpResponse(content_type='text/csv; charset=utf-8')\n    response['Content-Disposition']='attachment; filename=\"S3PL_FD_inventory.csv\"'\n    writer=csv.writer(response)\n    writer.writerow(['SKU','Description','Base unit','Eaches per case','Cases per pallet','Location','Type','On hand','Reserved','Available','Needs count','On hold','Counted at'])\n    for s in Stock.objects.filter(archived=False).select_related('part','location').order_by('part__sku','location__code'):\n        writer.writerow([safe_cell(v) for v in [s.part.sku,s.part.description,s.part.unit,s.part.units_per_case,s.part.cases_per_pallet,s.location.code,s.kind,s.on_hand,s.reserved,s.available,s.count_required,s.held,s.last_counted_at]])\n    return response\n\n\n@access()\ndef packing_slip(request,pk):\n    order=get_object_or_404(Order,pk=pk)\n    return render(request,'packing_slip.html',ctx(request,order=order,shipments=order.shipments.prefetch_related('lines__line__part'),lines=order.lines.select_related('part')))\n"
  },
