    "sha256": "2d4ad99b6b933b13f82f896d36bc7827491e604afb6741e77bc8c22ca26a14ec",
    "text": "\"\"\"Apply only Colin's approved bin rules to untouched original ICC test stock.\"\"\"\nfrom decimal import Decimal\nfrom django.db import transaction\nfrom .models import Part,Stock,Location,Allocation,Event\nfrom .operations import require_warehouse\n\nIMPORT_ID='5fddbc5d-3ec2-4bcb-a774-af4d2d73d5ea'\n\ndef approved_bin(source):\n    bins=list(dict.fromkeys(str(source.get(k,'')).strip() for k in ('L','O') if str(source.get(k,'')).strip()))\n    real=[b for b in bins if b.upper() not in ('TBD','MST BX')]\n    if len(real)==1: return real[0]\n    if not real and len(bins)==1: return bins[0]\n    return None  # Do not split H20 H24, guess between real bins, or invent blank bins.\n\n\n@transaction.atomic\ndef correct_locations(actor,apply=False):\n    require_warehouse(actor)\n    events=list(Event.objects.filter(action='ICC_TEST_IMPORT',entry__import_id=IMPORT_ID).select_related('stock').order_by('pk'))\n    grouped={}\n    for event in events: grouped.setdefault(event.stock.part_id,[]).append(event)\n    parts=list(Part.objects.select_for_update().filter(pk__in=grouped).order_by('pk'))\n    results=[]\n    for part in parts:\n        originals=grouped[part.pk];target=approved_bin(originals[0].entry['source'])\n        def record(status,reason): results.append(dict(sku=part.sku,status=status,reason=reason,target=target or ''))\n        if not target: record('REVIEW','Multiple real bins or blank source bin');continue\n        stocks=list(Stock.objects.select_for_update().filter(part=part).select_related('location').order_by('pk'))\n        if Event.objects.filter(stock__part=part,action='ICC_LOCATION_CORRECTION').exists(): record('UNCHANGED','Already corrected');continue\n        originals_by_stock={e.stock_id:e for e in originals}\n        if set(originals_by_stock)!={s.pk for s in stocks} or Allocation.objects.filter(stock__part=part).exists() or Event.objects.filter(stock__part=part).exclude(action='ICC_TEST_IMPORT').exists():\n            record('REVIEW','Activity or additional bin records since import; balances preserved');continue\n        if any(s.reserved or s.held or s.count_required or s.last_counted_at or s.archived or s.on_hand!=originals_by_stock[s.pk].after for s in stocks):\n            record('REVIEW','Balance/count/hold changed since import; preserved');continue\n        keep=next((s for s in stocks if s.location.code==target),stocks[0])\n        total=sum((s.on_hand for s in stocks),Decimal(0))\n        if len(stocks)==1 and keep.location.code==target: record('UNCHANGED','Source bin already retained');continue\n        record('APPLY' if apply else 'READY',f'Keep {total} EA in {target}; archive only superseded empty records')\n        if not apply: continue\n        old=[dict(id=s.pk,location=s.location.code,on_hand=str(s.on_hand)) for s in stocks]\n        location,_=Location.objects.get_or_create(code=target)\n        for stock in stocks:\n            before=stock.on_hand\n            if stock.pk==keep.pk:\n                stock.location=location;stock.on_hand=total\n            else:\n                stock.on_hand=0;stock.archived=True\n            stock.save(update_fields=['location','on_hand','archived'])\n            Event.objects.create(actor=actor,stock=stock,action='ICC_LOCATION_CORRECTION',before=before,after=stock.on_hand,\n                entry={'prior_bins':old,'target':target,'archived':stock.archived},note='Approved source-bin rules only. Total quantity preserved; not a physical count.')\n    return results\n"
  },
  "warehouse/management/commands/correct_icc_locations.py": {
    "previous": [
      null
    ],
    "sha256": "d9c805129a63b31ea79087dfcd3f83eaea98042a55c77c7841852f566feea84a",
    "text": "from collections import Counter\nfrom django.contrib.auth import get_user_model\nfrom django.core.management.base import BaseCommand,CommandError\nfrom warehouse.icc_locations import correct_locations\n\nclass Command(BaseCommand):\n    help='Preview/apply approved ICC bin corrections; skip records with activity.'\n    def add_arguments(self,parser):\n        parser.add_argument('--actor',required=True)\n        parser.add_argument('--apply',action='store_true')\n    def handle(self,*args,**options):\n        try: actor=get_user_model().objects.get(username=options['actor'])\n        except get_user_model().DoesNotExist: raise CommandError('User not found.')\n        try: rows=correct_locations(actor,options['apply'])\n        except PermissionError as exc: raise CommandError(str(exc))\n        for row in rows:\n            if row['status']!='UNCHANGED': self.stdout.write(f\"{row['status']} | {row['sku']} | {row['reason']}\")\n        self.stdout.write(str(dict(Counter(r['status'] for r in rows))))\n        if not options['apply']: self.stdout.write('Preview only. Add --apply to make the listed READY corrections.')\n"
  },
