    "text": "import hashlib\nimport uuid\nfrom django.db import transaction\nfrom django.utils import timezone\nfrom .models import StoreLocation,Part,OrderUpload,Event\nfrom .services import portal_user,quantity,WorkflowError,submit_order\nfrom .tabular import read_table\n\nHEADERS=['Store Number','Part Number','Quantity EA','Order Reference']\n\n\n@transaction.atomic\ndef preview_upload(actor,content,filename):\n    if not portal_user(actor): raise PermissionError('Portal access required.')\n    digest=hashlib.sha256(content).hexdigest()\n    existing=OrderUpload.objects.select_for_update().filter(actor=actor,checksum=digest).first()\n    if existing and existing.submitted_at:return existing\n    rows=read_table(content,filename,HEADERS,max_rows=2000)\n    stores={s.store_number:s for s in StoreLocation.objects.filter(customer_code='FD',active=True,store_number__in=[r['Store Number'] for r in rows])}\n    parts={p.sku:p for p in Part.objects.filter(sku__in=[r['Part Number'] for r in rows])}\n    grouped={}\n    for n,row in enumerate(rows,2):\n        number=row['Store Number'];sku=row['Part Number'];reference=row['Order Reference']\n        if number not in stores: raise WorkflowError(f'Row {n}: store {number} is not in the active FD directory.')\n        if sku not in parts or parts[sku].unit!='EA': raise WorkflowError(f'Row {n}: part {sku} must exist with EA confirmed.')\n        qty=quantity(row['Quantity EA'])\n        if qty!=qty.to_integral_value():raise WorkflowError(f'Row {n}: use whole EA quantities.')\n        if len(reference)>150:raise WorkflowError(f'Row {n}: order reference is too long.')\n        key=(number,reference)\n        group=grouped.setdefault(key,{'store_id':stores[number].pk,'details':stores[number].order_details(),'reference':reference,'items':{}})\n        group['items'][sku]=str(quantity(Decimal(group['items'].get(sku,'0'))+qty))\n    if len(grouped)>200:raise WorkflowError('Use at most 200 store/reference groups per file.')\n    upload,_=OrderUpload.objects.get_or_create(actor=actor,checksum=digest,defaults={'filename':filename[:255],'preview':list(grouped.values())})\n    upload=OrderUpload.objects.select_for_update().get(pk=upload.pk)\n    if not upload.submitted_at:\n        upload.preview=list(grouped.values());upload.save(update_fields=['preview'])\n    return upload\n\n\nfrom decimal import Decimal\n\n@transaction.atomic\ndef submit_upload(actor,upload_id):\n    if not portal_user(actor): raise PermissionError('Portal access required.')\n    upload=OrderUpload.objects.select_for_update().get(pk=upload_id,actor=actor)\n    if upload.submitted_at:return upload\n    # Lock all items in one consistent order before submitting any of the store orders.\n    skus={sku for group in upload.preview for sku in group['items']}\n    list(Part.objects.select_for_update().filter(sku__in=skus).order_by('pk'))\n    ids=[]\n    for i,group in enumerate(upload.preview):\n        store=StoreLocation.objects.filter(pk=group['store_id'],customer_code='FD',active=True).first()\n        if not store or store.order_details()!=group['details']:\n            raise WorkflowError('A store address changed after preview. Return to Upload orders and upload the file again to refresh the preview before confirming.')\n        details={**group['details'],'store_location':store,'reference':group['reference'],'notes':'Excel / CSV order upload','allow_backorder':True,'priority':'NORMAL'}\n        order=submit_order(actor,details,[(sku,qty,'EA') for sku,qty in group['items'].items()],uuid.uuid5(upload.pk,str(i)))\n        ids.append(str(order.pk))\n    upload.order_ids=ids;upload.submitted_at=timezone.now();upload.save(update_fields=['order_ids','submitted_at'])\n    Event.objects.create(actor=actor,action='ORDER_FILE_SUBMITTED',entry={'upload':str(upload.pk),'sha256':upload.checksum,'orders':ids},note=upload.filename)\n    return upload\n"
  },
