    "text": "import csv\nfrom django.contrib import messages\nfrom django.http import HttpResponse\nfrom django.shortcuts import get_object_or_404,redirect,render\nfrom .views import access,ctx\nfrom .update_views import ReportForm\nfrom .models import OrderUpload,Order\nfrom .services import WorkflowError\nfrom .order_upload import HEADERS,preview_upload,submit_upload\n\n\n@access()\ndef upload(request):\n    form=ReportForm(request.POST or None,request.FILES or None)\n    form.fields['report'].label='Order file (XLSX or CSV)'\n    if request.method=='POST' and form.is_valid():\n        try:\n            file=form.cleaned_data['report'];batch=preview_upload(request.user,file.read(),file.name)\n            return redirect('order_upload_preview',pk=batch.pk)\n        except WorkflowError as exc:form.add_error(None,str(exc))\n    return render(request,'order_upload.html',ctx(request,form=form))\n\n\n@access()\ndef preview(request,pk):\n    batch=get_object_or_404(OrderUpload,pk=pk,actor=request.user)\n    if request.method=='POST':\n        try:batch=submit_upload(request.user,batch.pk)\n        except WorkflowError as exc:messages.error(request,str(exc))\n        else:messages.success(request,f'{len(batch.order_ids)} orders submitted. Repeating this confirmation cannot create duplicates.')\n        return redirect('order_upload_preview',pk=pk)\n    return render(request,'order_upload_preview.html',ctx(request,batch=batch,orders=Order.objects.filter(pk__in=batch.order_ids)))\n\n\n@access()\ndef template(request):\n    response=HttpResponse(content_type='text/csv; charset=utf-8')\n    response['Content-Disposition']='attachment; filename=\"FD_order_upload_template.csv\"'\n    csv.writer(response).writerow(HEADERS)\n    return response\n"
