    "text": "from decimal import Decimal\nfrom django.db import transaction\nfrom django.db.models import Sum\nfrom .models import PurchaseOrder,PurchaseOrderLine,InboundReceipt,InboundReceiptLine,Part,Event,OperationKey\nfrom .operations import require_warehouse\nfrom .services import WorkflowError,quantity\nfrom .tabular import read_table\nimport hashlib\nimport uuid\n\nHEADERS=['PO Number','Vendor','Part Number','Expected EA']\n\n\n@transaction.atomic\ndef import_purchase_orders(actor,content,filename):\n    require_warehouse(actor)\n    rows=read_table(content,filename,HEADERS)\n    grouped={}\n    parts={p.sku:p for p in Part.objects.filter(sku__in=[r['Part Number'] for r in rows])}\n    for n,row in enumerate(rows,2):\n        number=row['PO Number'].upper();vendor=row['Vendor'];sku=row['Part Number']\n        qty=quantity(row['Expected EA'])\n        if not number or len(number)>100 or not vendor or len(vendor)>150: raise WorkflowError(f'Row {n}: enter PO number and vendor within the field limits.')\n        if sku not in parts or parts[sku].unit!='EA': raise WorkflowError(f'Row {n}: part {sku} must exist with EA confirmed.')\n        if qty!=qty.to_integral_value(): raise WorkflowError(f'Row {n}: Expected EA must be a whole number.')\n        group=grouped.setdefault(number,{'vendor':vendor,'items':{}})\n        if group['vendor']!=vendor or sku in group['items']: raise WorkflowError(f'Row {n}: duplicate PO/part or inconsistent vendor.')\n        group['items'][sku]=qty\n    # Serializes overlapping imports and avoids race-created duplicate POs.\n    lock,_=OperationKey.objects.get_or_create(key=uuid.uuid5(uuid.NAMESPACE_URL,'s3pl-fd-po-import-lock'),defaults={'actor':actor,'fingerprint':'PO import lock'})\n    OperationKey.objects.select_for_update().get(pk=lock.pk)\n    digest=hashlib.sha256(content).hexdigest()\n    key=uuid.uuid5(uuid.NAMESPACE_URL,'s3pl-fd-po-report:'+digest)\n    if OperationKey.objects.filter(pk=key).exists(): return {'unchanged':True,'orders':0,'lines':0}\n    changes=[]\n    for number,group in sorted(grouped.items()):\n        po,created=PurchaseOrder.objects.get_or_create(number=number,defaults={'vendor':group['vendor'],'created_by':actor})\n        if po.vendor!=group['vendor']: raise WorkflowError(f'PO {number}: vendor differs from the saved PO. Review it before importing.')\n        for sku,expected in group['items'].items():\n            line,new=PurchaseOrderLine.objects.get_or_create(purchase_order=po,part=parts[sku],defaults={'expected_quantity':expected})\n            if not new and line.expected_quantity!=expected:\n                raise WorkflowError(f'PO {number}, {sku}: expected quantity differs from the saved PO. Use the PO detail correction form with a reason.')\n            if new: changes.append({'po':number,'sku':sku,'expected':str(expected)})\n    OperationKey.objects.create(key=key,actor=actor,fingerprint=digest)\n    Event.objects.create(actor=actor,action='PO_IMPORT',entry={'sha256':digest,'new_lines':changes},note=filename[:255])\n    return {'unchanged':False,'orders':len(grouped),'lines':len(changes)}\n\n\ndef progress(po):\n    accepted=dict(InboundReceiptLine.objects.filter(receipt__status='POSTED',po_number=po.number)\n                  .values('sku').annotate(total=Sum('accepted_quantity')).values_list('sku','total'))\n    rows=[]\n    for line in po.lines.select_related('part').order_by('part__sku'):\n        got=accepted.get(line.part.sku,Decimal(0));expected=line.expected_quantity\n        rows.append({'line':line,'accepted':got,'remaining':max(Decimal(0),expected-got),'over':max(Decimal(0),got-expected)})\n    total=sum((r['line'].expected_quantity for r in rows),Decimal(0))\n    filled=sum((min(r['accepted'],r['line'].expected_quantity) for r in rows),Decimal(0))\n    return {'po':po,'rows':rows,'expected':total,'accepted':sum((r['accepted'] for r in rows),Decimal(0)),\n            'percent':filled*100/total if total else 0,'complete':bool(rows) and all(r['remaining']==0 for r in rows),\n            'unmatched':[(sku,q) for sku,q in accepted.items() if sku not in {r['line'].part.sku for r in rows}]}\n\n\n@transaction.atomic\ndef correct_expected(actor,line_id,amount,note):\n    require_warehouse(actor)\n    if not note.strip(): raise WorkflowError('Enter a correction reason.')\n    amount=quantity(amount)\n    if amount!=amount.to_integral_value(): raise WorkflowError('Use a whole number of eaches.')\n    line=PurchaseOrderLine.objects.select_for_update().select_related('purchase_order','part').get(pk=line_id)\n    before=line.expected_quantity;line.expected_quantity=amount;line.save(update_fields=['expected_quantity'])\n    Event.objects.create(actor=actor,action='PO_EXPECTED_CORRECTION',before=before,after=amount,entry={'po':line.purchase_order.number,'sku':line.part.sku},note=note[:500])\n\n\n@transaction.atomic\ndef correct_accepted(actor,line_id,amount,note,po_number=None):\n    require_warehouse(actor)\n    if not note.strip(): raise WorkflowError('Enter the inspection / correction reason.')\n    amount=quantity(amount,allow_zero=True)\n    line=InboundReceiptLine.objects.select_for_update().select_related('receipt','stock').get(pk=line_id)\n    if line.receipt.status!='POSTED' or amount>line.quantity or amount!=amount.to_integral_value(): raise WorkflowError('Accepted EA must be a whole number within the posted received quantity.')\n    if amount>line.accepted_quantity and line.stock.held: raise WorkflowError('Complete inspection and release the stock hold before accepting it against the PO.')\n    before_po=line.po_number\n    if po_number is not None:\n        if len(po_number.strip())>100: raise WorkflowError('PO number must be at most 100 characters.')\n        line.po_number=po_number.strip().upper()\n    before=line.accepted_quantity;line.accepted_quantity=amount;line.save(update_fields=['accepted_quantity','po_number'])\n    Event.objects.create(actor=actor,receipt=line.receipt,stock=line.stock,action='PO_ACCEPTED_CORRECTION',before=before,after=amount,\n        entry={'po':line.po_number,'prior_po':before_po,'sku':line.sku,'receipt_line':line.pk},note=note[:500])\n\n\n@transaction.atomic\ndef correct_receipt_po(actor,receipt_id,number,note):\n    require_warehouse(actor)\n    number=number.strip().upper()\n    if len(number)>100 or not note.strip(): raise WorkflowError('Enter a valid PO number and a reason.')\n    receipt=InboundReceipt.objects.select_for_update().get(pk=receipt_id,status='POSTED')\n    before=receipt.po_number;receipt.po_number=number;receipt.save(update_fields=['po_number'])\n    updated=list(receipt.lines.filter(po_number=before).values_list('pk',flat=True))\n    receipt.lines.filter(pk__in=updated).update(po_number=number)\n    Event.objects.create(actor=actor,receipt=receipt,action='RECEIPT_PO_CORRECTION',entry={'before':before,'after':number,'lines_updated':updated},note=note[:500])\n"
