    "sha256": "2a6d952b23a39200c743782fbc88c5d71b04687941951c5f427886d64a1afa07",
    "text": "\"\"\"Family Dollar ship-to directory. Warehouse bins are a separate model.\"\"\"\nimport hashlib\nimport io\nimport re\nimport uuid\nfrom pathlib import Path\nfrom zipfile import ZipFile, BadZipFile\n\nfrom django.core.exceptions import ValidationError\nfrom django.db import transaction\nfrom django.utils import timezone\nfrom openpyxl import load_workbook\n\nfrom .models import Event, OperationKey, StoreLocation\nfrom .services import warehouse_user\n\nHEADERS=['Store Number','Shipping Address','Shipping City','Shipping State/Province',\n         'Shipping Zip/Postal Code','Shipping County','Location Type']\nFIELDS=['store_number','address','city','state','postal_code','county','location_type']\nMAX_BYTES=10*1024*1024\nMAX_ROWS=20000\n\n\ndef read_report(content):\n    if len(content)>MAX_BYTES:\n        raise ValidationError('The location report must be 10 MB or smaller.')\n    try:\n        with ZipFile(io.BytesIO(content)) as archive:\n            if sum(x.file_size for x in archive.infolist())>80*1024*1024:\n                raise ValidationError('The expanded location report is too large.')\n        workbook=load_workbook(io.BytesIO(content),read_only=True,data_only=False,keep_links=False)\n    except ValidationError:\n        raise\n    except Exception as exc:\n        raise ValidationError('Upload a valid Excel .xlsx location report.') from exc\n    try:\n        matches=[]\n        for sheet in workbook:\n            for cells in sheet.iter_rows(min_row=1,max_row=10,max_col=30):\n                labels=[str(c.value or '').strip() for c in cells]\n                if all(h in labels for h in HEADERS):\n                    matches.append((sheet,cells[0].row,[labels.index(h) for h in HEADERS]))\n                    break\n        if len(matches)!=1:\n            raise ValidationError('Expected one sheet with the seven FD Active Location Report column headers.')\n        sheet,header,columns=matches[0]\n        rows=[];seen=set()\n        for cells in sheet.iter_rows(min_row=header+1,max_row=header+MAX_ROWS+1,max_col=max(columns)+1):\n            picked=[cells[i] for i in columns]\n            if not any(c.value not in (None,'') for c in picked):\n                continue\n            if len(rows)>=MAX_ROWS:\n                raise ValidationError('The report exceeds 20,000 locations.')\n            if any(c.data_type in ('f','e') for c in picked):\n                raise ValidationError(f'Row {cells[0].row}: use values, not formulas or Excel errors.')\n            values=[str(c.value).strip() if c.value is not None else '' for c in picked]\n            # Numeric ZIPs in Excel can lose leading zeroes. FD addresses use US ZIPs.\n            if isinstance(picked[4].value,int):\n                values[4]=str(picked[4].value).zfill(5)\n            data=dict(zip(FIELDS,values));data['state']=data['state'].upper()\n            if not data['store_number'] or data['store_number'] in seen:\n                raise ValidationError(f'Row {cells[0].row}: missing or duplicate store number {data[\"store_number\"]}.')\n            if not re.fullmatch(r'\\d{5}(?:-\\d{4})?',data['postal_code']):\n                raise ValidationError(f'Row {cells[0].row}: ZIP must contain five digits, optionally followed by -XXXX.')\n            if not re.fullmatch(r'[A-Z]{2}',data['state']):\n                raise ValidationError(f'Row {cells[0].row}: state must be two letters.')\n            try:\n                StoreLocation(**data).full_clean(validate_unique=False,validate_constraints=False)\n            except ValidationError as exc:\n                raise ValidationError(f'Row {cells[0].row}: {exc}') from exc\n            seen.add(data['store_number']);rows.append(data)\n        if not rows:\n            raise ValidationError('The location report contains no stores.')\n        return rows\n    except ValidationError:\n        raise\n    except Exception as exc:\n        raise ValidationError('The report could not be read. Save it as an Excel .xlsx file and try again.') from exc\n    finally:\n        workbook.close()\n\n\ndef import_report(actor,content,filename):\n    if not warehouse_user(actor):\n        raise PermissionError('Warehouse access required.')\n    rows=read_report(content)  # Validate everything before changing any directory records.\n    checksum=hashlib.sha256(content).hexdigest()\n    key=uuid.uuid5(uuid.NAMESPACE_URL,'s3pl:fd-store-directory:'+checksum)\n    with transaction.atomic():\n        # Serialize directory imports, including two different reports uploaded together.\n        lock_key=uuid.uuid5(uuid.NAMESPACE_URL,'s3pl:fd-store-directory-lock')\n        OperationKey.objects.get_or_create(key=lock_key,defaults={'actor':actor,'fingerprint':'FD_STORE_DIRECTORY_LOCK'})\n        OperationKey.objects.select_for_update().get(key=lock_key)\n        marker,new=OperationKey.objects.get_or_create(key=key,defaults={'actor':actor,'fingerprint':'FD_STORE_DIRECTORY:'+checksum})\n        if not new:\n            return {'total':len(rows),'created':0,'updated':0,'unchanged':len(rows),'repeated':True}\n        existing={s.store_number:s for s in StoreLocation.objects.select_for_update().filter(customer_code='FD')}\n        created=[];updated=[];changes=[];now=timezone.now()\n        source=Path(filename).name[:255]\n        for data in rows:\n            store=existing.get(data['store_number'])\n            if store is None:\n                created.append(StoreLocation(**data,source_report=source))\n                changes.append({'store':data['store_number'],'before':None,'after':data})\n            elif any(getattr(store,f)!=data[f] for f in FIELDS) or not store.active:\n                changes.append({'store':data['store_number'],'before':{f:getattr(store,f) for f in FIELDS}|{'active':store.active},'after':data|{'active':True}})\n                for field,value in data.items():\n                    setattr(store,field,value)\n                store.active=True;store.source_report=source;store.updated_at=now\n                updated.append(store)\n        StoreLocation.objects.bulk_create(created,batch_size=500)\n        StoreLocation.objects.bulk_update(updated,FIELDS+['active','source_report','updated_at'],batch_size=250)\n        counts={'total':len(rows),'created':len(created),'updated':len(updated),'unchanged':len(rows)-len(created)-len(updated),'repeated':False}\n        Event.objects.create(actor=actor,action='FD_STORE_DIRECTORY_IMPORT',\n                             entry={'sha256':checksum,'source':source,'counts':counts,'changes':changes},\n                             note=f'FD ship-to directory imported: {len(rows)} stores. Existing orders retain their delivery addresses.')\n        return counts\n"
  },
