    "sha256": "eddefbb0e877de3a51dc6c686fee6d6ec7f4d43872cf1c7fe9b09fa22cea0f99",
    "text": "from django import forms\nfrom django.contrib import messages\nfrom django.core.exceptions import ValidationError\nfrom django.db.models import Q,Case,When,Value,IntegerField\nfrom django.http import JsonResponse\nfrom django.shortcuts import render,redirect\nfrom django.views.decorators.cache import never_cache\nfrom django.views.decorators.http import require_GET\n\nfrom .models import StoreLocation\nfrom .store_directory import import_report,MAX_BYTES\nfrom .views import access,ctx\n\n\n@never_cache\n@require_GET\n@access()\ndef store_search(request):\n    query=request.GET.get('q','').strip()[:100]\n    if len(query)<2 and not query.isdigit():\n        return JsonResponse({'results':[],'more':False})\n    stores=StoreLocation.objects.filter(customer_code='FD',active=True)\n    for word in query.split():\n        term=word.lstrip('#')\n        match=Q(store_number__icontains=term)|Q(postal_code__icontains=term)|Q(city__icontains=term)|Q(state__iexact=term)|Q(address__icontains=term)|Q(county__icontains=term)\n        if term.isdigit(): match |= Q(store_number=term.lstrip('0') or '0')\n        stores=stores.filter(match)\n    stores=stores.annotate(rank=Case(When(store_number=query.lstrip('#'),then=Value(0)),default=Value(1),output_field=IntegerField())).order_by('rank','store_number')\n    results=list(stores[:21])\n    return JsonResponse({'results':[dict(id=s.pk,**s.order_details()) for s in results[:20]],'more':len(results)>20})\n\n\nclass DirectoryUpload(forms.Form):\n    report=forms.FileField(label='FD Active Location Report (.xlsx)',widget=forms.ClearableFileInput(attrs={'accept':'.xlsx'}))\n    def clean_report(self):\n        upload=self.cleaned_data['report']\n        if not upload.name.lower().endswith('.xlsx'):\n            raise forms.ValidationError('Choose the Excel .xlsx report.')\n        if upload.size>MAX_BYTES:\n            raise forms.ValidationError('Choose a report smaller than 10 MB.')\n        return upload\n\n\n@access(warehouse=True)\ndef directory_import(request):\n    form=DirectoryUpload(request.POST or None,request.FILES or None)\n    if request.method=='POST' and form.is_valid():\n        report=form.cleaned_data['report']\n        try:\n            counts=import_report(request.user,report.read(),report.name)\n        except ValidationError as exc:\n            form.add_error('report',exc)\n        else:\n            text=(f'This report was already imported ({counts[\"total\"]:,} stores).' if counts['repeated'] else\n                  f'Store directory updated: {counts[\"created\"]:,} added, {counts[\"updated\"]:,} updated, {counts[\"unchanged\"]:,} unchanged.')\n            messages.success(request,text)\n            return redirect('directory_import')\n    return render(request,'store_directory_import.html',ctx(request,form=form,store_count=StoreLocation.objects.filter(customer_code='FD',active=True).count()))\n"
  },
