    "text": "\"\"\"Bounded, formula-free customer data imports (CSV or XLSX).\"\"\"\nimport csv\nimport io\nimport zipfile\nfrom openpyxl import load_workbook\nfrom .services import WorkflowError\n\n\ndef read_table(content, filename, headers, max_rows=20000):\n    if len(content)>10*1024*1024: raise WorkflowError('Use a file under 10 MB.')\n    try:\n        if filename.lower().endswith('.xlsx'):\n            with zipfile.ZipFile(io.BytesIO(content)) as archive:\n                if sum(i.file_size for i in archive.infolist())>80*1024*1024: raise WorkflowError('Workbook expands beyond the import limit.')\n            book=load_workbook(io.BytesIO(content),read_only=True,data_only=False,keep_links=False)\n            try:\n                sheet=book.worksheets[0]\n                if sheet.max_row and sheet.max_row>max_rows+1: raise WorkflowError(f'Use at most {max_rows} data rows.')\n                rows=[]\n                for row in sheet.iter_rows(max_row=max_rows+2,max_col=len(headers)+1):\n                    if any(c.data_type in ('f','e') for c in row): raise WorkflowError('Replace formulas and Excel errors with plain values before upload.')\n                    rows.append([str(c.value).strip() if c.value is not None else '' for c in row])\n            finally: book.close()\n        elif filename.lower().endswith('.csv'):\n            rows=list(csv.reader(io.StringIO(content.decode('utf-8-sig'))))\n        else: raise WorkflowError('Use an XLSX or UTF-8 CSV file.')\n    except WorkflowError: raise\n    except Exception as exc: raise WorkflowError('The file could not be read. Use the template columns and plain values.') from exc\n    if not rows or rows[0][:len(headers)]!=headers: raise WorkflowError('Expected header row: '+', '.join(headers))\n    rows=[r for r in rows[1:] if any(str(v).strip() for v in r)]\n    if not rows or len(rows)>max_rows: raise WorkflowError(f'Use 1\u2013{max_rows} data rows.')\n    result=[]\n    for i,row in enumerate(rows,2):\n        if len(row)<len(headers) or any(row[len(headers):]): raise WorkflowError(f'Row {i}: incorrect column count.')\n        values=[str(v).strip() for v in row[:len(headers)]]\n        if any(len(v)>500 for v in values): raise WorkflowError(f'Row {i}: a value is too long.')\n        result.append(dict(zip(headers,values)))\n    return result\n"
  },
