    "text": "import io\nimport uuid\nfrom unittest.mock import patch\nfrom openpyxl import Workbook\nfrom django.contrib.auth import get_user_model\nfrom django.contrib.auth.models import Group\nfrom django.test import TestCase,override_settings\nfrom .models import StoreLocation,Part,Stock,Location,Order,OrderUpload\nfrom .order_upload import preview_upload,submit_upload,HEADERS\nfrom .services import WorkflowError\nfrom .test_receiving import SETTINGS\n\n\n@override_settings(**SETTINGS)\nclass OrderUploadTests(TestCase):\n    def setUp(self):\n        self.fd=get_user_model().objects.create_user('fd')\n        self.fd.groups.add(Group.objects.get_or_create(name='FD Corporate')[0])\n        self.wh=get_user_model().objects.create_superuser('office')\n        self.stores=[StoreLocation.objects.create(store_number=n,address='1 Main St',city='Newark',state='NJ',postal_code='07101') for n in ['100','200']]\n        part=Part.objects.create(sku='001',unit='EA')\n        self.stock=Stock.objects.create(part=part,location=Location.objects.create(code='P1'),kind='PICK',on_hand=8)\n        self.content=b'Store Number,Part Number,Quantity EA,Order Reference\\n100,001,5,TEST-A\\n200,001,6,TEST-B\\n'\n    def test_preview_then_multi_store_submit_repeat_once_with_backorder(self):\n        batch=preview_upload(self.fd,self.content,'orders.csv')\n        self.assertFalse(Order.objects.exists());self.assertEqual(len(batch.preview),2)\n        done=submit_upload(self.fd,batch.pk);submit_upload(self.fd,batch.pk)\n        self.assertEqual(len(done.order_ids),2);self.assertEqual(Order.objects.count(),2)\n        self.stock.refresh_from_db();self.assertEqual(self.stock.reserved,8)\n        self.assertEqual(sum(l.backordered for o in Order.objects.all() for l in o.lines.all()),3)\n        self.assertEqual(preview_upload(self.fd,self.content,'same-file-renamed.csv').pk,batch.pk)\n        self.assertTrue(all(o.postal_code=='07101' for o in Order.objects.all()))\n    def test_invalid_row_blocks_entire_batch(self):\n        for bad in [b'999,001,1,TEST\\n',b'100,MISSING,1,TEST\\n',b'100,001,0.5,TEST\\n']:\n            with self.assertRaises(WorkflowError):preview_upload(self.fd,self.content+bad,'orders.csv')\n        self.assertFalse(OrderUpload.objects.exists())\n    def test_changed_address_requires_new_preview_and_submission_is_atomic(self):\n        batch=preview_upload(self.fd,self.content,'orders.csv')\n        self.stores[1].address='2 Main St';self.stores[1].save()\n        with self.assertRaises(WorkflowError):submit_upload(self.fd,batch.pk)\n        self.assertFalse(Order.objects.exists());self.stock.refresh_from_db();self.assertEqual(self.stock.reserved,0)\n        refreshed=preview_upload(self.fd,self.content,'orders.csv');submit_upload(self.fd,refreshed.pk)\n        self.assertEqual(Order.objects.get(store='200').address,'2 Main St')\n    def test_repeat_item_rows_merge_but_references_separate_orders(self):\n        batch=preview_upload(self.wh,self.content+b'100,001,2,TEST-A\\n100,001,1,TEST-C\\n','orders.csv')\n        self.assertEqual(len(batch.preview),3);submit_upload(self.wh,batch.pk)\n        self.assertEqual(Order.objects.get(reference='TEST-A').lines.get().quantity,7)\n    def test_xlsx_and_formula_rejection(self):\n        workbook=Workbook();sheet=workbook.active;sheet.append(HEADERS);sheet.append(['100','001',2,'TEST'])\n        stream=io.BytesIO();workbook.save(stream)\n        batch=preview_upload(self.fd,stream.getvalue(),'orders.xlsx');self.assertEqual(batch.preview[0]['items'],{'001':'2'})\n        sheet['C2']='=1+1';stream=io.BytesIO();workbook.save(stream)\n        with self.assertRaises(WorkflowError):preview_upload(self.fd,stream.getvalue(),'orders.xlsx')\n    def test_preview_and_template_pages_and_owner_access(self):\n        batch=preview_upload(self.fd,self.content,'orders.csv')\n        self.client.force_login(self.fd)\n        for url in ['/orders/upload/','/orders/upload/template/',f'/orders/upload/{batch.pk}/']:\n            self.assertEqual(self.client.get(url).status_code,200,url)\n        self.assertContains(self.client.get(f'/orders/upload/{batch.pk}/'),'TEST-A')\n        self.client.force_login(self.wh)\n        self.assertEqual(self.client.get(f'/orders/upload/{batch.pk}/').status_code,404)\n"
  },
