    "text": "import uuid\nfrom datetime import timedelta\nfrom decimal import Decimal\nfrom django.contrib.auth import get_user_model\nfrom django.contrib.auth.models import Group\nfrom django.test import TestCase,TransactionTestCase,override_settings\nfrom django.utils import timezone\nfrom .models import (Part,Stock,Location,Order,Event,ReceiptGroup,InboundReceipt,ReceiptEmail,\n                     PickRelease,PurchaseOrder,Allocation)\nfrom .tests import DETAILS\nfrom .test_receiving import SETTINGS\nfrom .services import submit_order,transition_order,transfer_stock,WorkflowError\nfrom .receiving import save_receipt,post_receipt\nfrom .backorders import change_priority\nfrom .operations import set_hold\nfrom .reporting import stock_summary,due_counts\nfrom .purchase_orders import import_purchase_orders,progress,correct_accepted,correct_expected,correct_receipt_po\nfrom .icc_locations import correct_locations,approved_bin,IMPORT_ID\n\n\n@override_settings(**SETTINGS)\nclass ReleaseUpdateTests(TestCase):\n    def setUp(self):\n        self.wh=get_user_model().objects.create_superuser('office')\n        self.fd=get_user_model().objects.create_user('fd')\n        self.fd.groups.add(Group.objects.get_or_create(name='FD Corporate')[0])\n        self.part=Part.objects.create(sku='001',unit='EA',units_per_case=12)\n        self.stock=Stock.objects.create(part=self.part,location=Location.objects.create(code='P1'),kind='PICK',on_hand=0)\n        self.group=ReceiptGroup.objects.create(name='FD',addresses='receipts@example.com')\n    def order(self,qty=20): return submit_order(self.fd,DETAILS,[(self.part.sku,qty,'EA')],uuid.uuid4())\n    def draft(self,qty=15,stock=None,po='000123'):\n        stock=stock or self.stock\n        row=dict(sku=stock.part.sku,location=stock.location.code,quantity=str(qty),unit='EA',loose_eaches='0',case_pack=str(stock.part.units_per_case or ''),pallet_cases='',note='',damaged=stock.held)\n        return save_receipt(self.wh,uuid.uuid4(),None,0,dict(supplier='Vendor',received_date=timezone.localdate(),reference='BOL-1',po_number=po,group=self.group,notes=''),[row])\n    def receipt(self,*args,**kwargs):\n        r=self.draft(*args,**kwargs);return post_receipt(self.wh,r.pk,r.revision)\n    def po(self,rows='000123,Vendor,001,20\\n'):\n        data=('PO Number,Vendor,Part Number,Expected EA\\n'+rows).encode()\n        return import_purchase_orders(self.wh,data,'po.csv')\n\n    def test_partial_ship_then_two_receipts_release_only_remaining_once(self):\n        self.stock.on_hand=5;self.stock.save()\n        order=self.order(25);line=order.lines.get()\n        transition_order(self.wh,order.pk,'pick')\n        summary=stock_summary()[0]\n        self.assertEqual((summary['on_hand'],summary['allocated'],summary['available'],summary['staged']),(5,5,0,5))\n        transition_order(self.wh,order.pk,'pack',line_id=line.pk,amount=5,unit='EA',scan='001')\n        transition_order(self.wh,order.pk,'ship',carrier='UPS',tracking='TEST')\n        receipt=self.receipt(15);post_receipt(self.wh,receipt.pk,receipt.revision)\n        line.refresh_from_db();self.stock.refresh_from_db()\n        self.assertEqual((line.shipped,line.reserved_quantity,line.backordered),(5,15,5))\n        self.assertEqual((self.stock.on_hand,self.stock.reserved),(15,15))\n        self.assertEqual(PickRelease.objects.count(),1);self.assertEqual(ReceiptEmail.objects.count(),1)\n        self.assertEqual(receipt.pick_releases.get().order,order)\n        self.receipt(12);line.refresh_from_db();self.stock.refresh_from_db()\n        self.assertEqual((line.reserved_quantity,line.backordered,self.stock.available),(20,0,7))\n        self.assertEqual(PickRelease.objects.count(),2)\n    def test_fifo_and_audited_urgent_override(self):\n        first=self.order(10);second=self.order(10);urgent=self.order(10)\n        change_priority(self.wh,urgent.pk,'URGENT','Store opening')\n        self.receipt(15)\n        self.assertEqual(urgent.lines.get().reserved_quantity,10)\n        self.assertEqual(first.lines.get().reserved_quantity,5)\n        self.assertEqual(second.lines.get().reserved_quantity,0)\n        self.assertEqual(Event.objects.filter(action='ORDER_PRIORITY').count(),1)\n    def test_customer_cannot_raise_priority_or_use_cases(self):\n        with self.assertRaises(WorkflowError): submit_order(self.fd,DETAILS,[('001',1,'CASE')],uuid.uuid4())\n        order=submit_order(self.fd,{**DETAILS,'priority':'URGENT','allow_backorder':False},[('001',3,'EA')],uuid.uuid4())\n        self.assertEqual(order.priority,'NORMAL');self.assertTrue(order.allow_backorder)\n        with self.assertRaises(PermissionError): change_priority(self.fd,order.pk,'URGENT','test')\n        self.client.force_login(self.fd)\n        self.assertNotContains(self.client.get('/orders/new/'),'value=\"CASE\"')\n        self.assertEqual(self.client.post(f'/orders/{order.pk}/priority/',{'priority':'URGENT','note':'test'}).status_code,403)\n    def test_held_and_cancelled_do_not_allocate_then_inspection_release_does(self):\n        cancelled=self.order();transition_order(self.wh,cancelled.pk,'cancel')\n        waiting=self.order()\n        quarantine=Stock.objects.create(part=self.part,location=Location.objects.create(code='Q'),kind='OVERSTOCK',on_hand=0,held=True)\n        receipt=self.receipt(15,stock=quarantine)\n        self.assertEqual(receipt.lines.get().accepted_quantity,0)\n        self.assertFalse(PickRelease.objects.exists())\n        with self.assertRaises(WorkflowError): correct_accepted(self.wh,receipt.lines.get().pk,15,'Inspected')\n        set_hold(self.wh,quarantine.pk,False,'Inspected all goods')\n        self.assertEqual(waiting.lines.get().reserved_quantity,15)\n        self.assertEqual(cancelled.lines.get().reserved_quantity,0)\n        correct_accepted(self.wh,receipt.lines.get().pk,15,'Accepted after inspection')\n        self.assertEqual(receipt.lines.get().accepted_quantity,15)\n    def test_bad_receipt_rolls_back_all_stock_and_releases(self):\n        self.order();receipt=self.draft()\n        receipt.draft_lines.append({**receipt.draft_lines[0],'sku':'MISSING'});receipt.save()\n        with self.assertRaises(WorkflowError): post_receipt(self.wh,receipt.pk,receipt.revision)\n        self.stock.refresh_from_db();self.assertEqual(self.stock.on_hand,0)\n        self.assertFalse(PickRelease.objects.exists());self.assertFalse(ReceiptEmail.objects.exists())\n    def test_release_tracks_transfer_partial_pick_and_unpick(self):\n        order=self.order();self.receipt();release=PickRelease.objects.get()\n        target=Stock.objects.create(part=self.part,location=Location.objects.create(code='P2'),kind='PICK',on_hand=0)\n        transfer_stock(self.wh,self.stock.pk,target.pk,6,'Replenish',unit='EA')\n        self.assertEqual(sum(a.quantity for a in release.allocations.all()),15)\n        line=order.lines.get();transition_order(self.wh,order.pk,'pick',line_id=line.pk,amount=3,unit='EA')\n        self.assertEqual(sum(a.quantity for a in release.allocations.filter(state='PICKED')),3)\n        transition_order(self.wh,order.pk,'unpick',line_id=line.pk,amount=1,unit='EA',note='Correction')\n        self.assertEqual(sum(a.quantity for a in release.allocations.filter(state='PICKED')),2)\n    def test_po_per_item_progress_not_aggregate_and_reopens_on_correction(self):\n        second=Part.objects.create(sku='002',unit='EA')\n        stock2=Stock.objects.create(part=second,location=self.stock.location,kind='PICK',on_hand=0)\n        self.po('000123,Vendor,001,20\\n000123,Vendor,002,10\\n')\n        po=PurchaseOrder.objects.get()\n        first=self.receipt(30);self.assertFalse(progress(po)['complete'])\n        self.assertEqual(progress(po)['percent'],Decimal(200)/3)\n        self.receipt(10,stock=stock2);self.assertTrue(progress(po)['complete'])\n        correct_accepted(self.wh,first.lines.get().pk,19,'One unit rejected on review')\n        self.assertFalse(progress(po)['complete'])\n        correct_expected(self.wh,po.lines.get(part=self.part).pk,19,'Approved PO amendment')\n        self.assertTrue(progress(po)['complete'])\n    def test_po_import_repeat_no_overwrite_and_error_is_atomic(self):\n        self.po();result=self.po();self.assertTrue(result['unchanged'])\n        with self.assertRaises(WorkflowError): self.po('000123,Vendor,001,25\\n')\n        with self.assertRaises(WorkflowError): self.po('000999,Vendor,001,5\\n000123,Vendor,001,99\\n')\n        self.assertEqual(PurchaseOrder.objects.count(),1)\n        self.assertEqual(PurchaseOrder.objects.get().lines.get().expected_quantity,20)\n    def test_one_delivery_can_fill_multiple_pos_with_one_email(self):\n        self.po('000123,Vendor,001,15\\n000456,Vendor,001,5\\n')\n        receipt=self.draft(15)\n        receipt.draft_lines.append({**receipt.draft_lines[0],'quantity':'5','line_po':'000456'})\n        receipt.save();post_receipt(self.wh,receipt.pk,receipt.revision)\n        self.assertEqual(ReceiptEmail.objects.count(),1)\n        for po in PurchaseOrder.objects.all():self.assertTrue(progress(po)['complete'])\n        corrected=receipt.lines.get(po_number='000456')\n        correct_accepted(self.wh,corrected.pk,5,'PO number correction','000789')\n        self.assertFalse(progress(PurchaseOrder.objects.get(number='000456'))['complete'])\n    def test_po_import_after_receipt_and_reference_correction(self):\n        receipt=self.receipt(20,po='');self.po();po=PurchaseOrder.objects.get()\n        self.assertFalse(progress(po)['complete'])\n        correct_receipt_po(self.wh,receipt.pk,'000123','PO located on BOL')\n        self.assertTrue(progress(po)['complete'])\n        self.assertEqual(ReceiptEmail.objects.count(),1)\n        self.client.force_login(self.wh)\n        self.assertContains(self.client.get('/receipts/?vendor=Vendor&po=000123'),receipt.number)\n    def test_office_pages_and_customer_restrictions(self):\n        order=self.order();receipt=self.receipt();self.po();release=PickRelease.objects.get();po=PurchaseOrder.objects.get()\n        urls=['/work/',f'/releases/{release.pk}/','/purchase-orders/',f'/purchase-orders/{po.pk}/','/purchase-orders/template/',f'/receipts/{receipt.pk}/']\n        self.client.force_login(self.wh)\n        for url in urls: self.assertEqual(self.client.get(url).status_code,200,url)\n        self.client.force_login(self.fd)\n        for url in urls:self.assertEqual(self.client.get(url).status_code,403,url)\n\n\n@override_settings(**SETTINGS)\nclass BinCorrectionTests(TestCase):\n    def setUp(self): self.wh=get_user_model().objects.create_superuser('office')\n    def make(self,sku='001',bins=('MST BX','H20 H24'),stock_rows=(('ICC-TEST-UNASSIGNED',8),('H20 H24',0))):\n        part=Part.objects.create(sku=sku,unit='EA')\n        source={'C':sku,'L':bins[0],'O':bins[1],'I':'8','M':'999'}\n        for code,qty in stock_rows:\n            location,_=Location.objects.get_or_create(code=code)\n            stock=Stock.objects.create(part=part,location=location,kind='PICK',on_hand=qty)\n            Event.objects.create(actor=self.wh,stock=stock,action='ICC_TEST_IMPORT',after=qty,quantity=qty,entry={'import_id':IMPORT_ID,'source':source})\n        return part\n    def test_rules_keep_literals_and_do_not_split_codes(self):\n        for source,wanted in [({'L':'MST BX','O':'H20 H24'},'H20 H24'),({'L':'TBD','O':'J57'},'J57'),({'L':'TBD'},'TBD'),({'L':'MST BX'},'MST BX'),({'L':'J57','O':'J57'},'J57'),({'L':'P1','O':'P2'},None),({},None)]:\n            self.assertEqual(approved_bin(source),wanted)\n    def test_safe_consolidation_preserves_qty_audit_and_no_count(self):\n        part=self.make();self.assertEqual(correct_locations(self.wh)[0]['status'],'READY')\n        self.assertFalse(Stock.objects.filter(archived=True).exists())\n        self.assertEqual(correct_locations(self.wh,True)[0]['status'],'APPLY')\n        active=Stock.objects.get(part=part,archived=False)\n        self.assertEqual((active.location.code,active.on_hand),('H20 H24',8));self.assertIsNone(active.last_counted_at)\n        self.assertEqual(sum(s.on_hand for s in Stock.objects.filter(part=part)),8)\n        self.assertEqual(Event.objects.filter(action='ICC_TEST_IMPORT').count(),2)\n        self.assertEqual(correct_locations(self.wh,True)[0]['status'],'UNCHANGED')\n        self.assertFalse(any(s.archived for s in due_counts()))\n    def test_activity_blocks_correction(self):\n        part=self.make();stock=part.stock_set.first()\n        Event.objects.create(actor=self.wh,stock=stock,action='COUNT',note='Activity after import')\n        self.assertEqual(correct_locations(self.wh,True)[0]['status'],'REVIEW')\n        self.assertFalse(Stock.objects.filter(archived=True).exists())\n\n\nclass ReleaseConcurrencyTests(TransactionTestCase):\n    def test_overlapping_receipts_do_not_double_allocate_or_deadlock(self):\n        from django.db import connection,close_old_connections\n        if connection.vendor!='postgresql':self.skipTest('Requires PostgreSQL row locks.')\n        import threading\n        from concurrent.futures import ThreadPoolExecutor\n        actor=get_user_model().objects.create_superuser('office')\n        part=Part.objects.create(sku='001',unit='EA')\n        stock=Stock.objects.create(part=part,location=Location.objects.create(code='P1'),kind='PICK',on_hand=0)\n        group=ReceiptGroup.objects.create(name='FD',addresses='receipts@example.com')\n        order=submit_order(actor,{**DETAILS,'allow_backorder':True},[('001',20,'EA')],uuid.uuid4())\n        receipts=[]\n        for _ in range(2):\n            receipts.append(save_receipt(actor,uuid.uuid4(),None,0,dict(supplier='V',received_date=timezone.localdate(),reference='B',group=group,notes=''),[dict(sku='001',location='P1',quantity='15',unit='EA',loose_eaches='0',case_pack='',pallet_cases='',damaged=False)]))\n        barrier=threading.Barrier(2)\n        def post(receipt):\n            close_old_connections()\n            try:\n                with connection.cursor() as cursor:cursor.execute(\"SET lock_timeout='5s'\")\n                user=get_user_model().objects.get(pk=actor.pk);barrier.wait(timeout=10)\n                post_receipt(user,receipt.pk,receipt.revision)\n            finally:close_old_connections()\n        with ThreadPoolExecutor(max_workers=2) as pool:list(pool.map(post,receipts))\n        stock.refresh_from_db();self.assertEqual((stock.on_hand,stock.reserved),(30,20))\n        self.assertEqual(order.lines.get().backordered,0)\n        self.assertEqual(sum(a.quantity for a in Allocation.objects.all()),20)\n"
