    "text": "import uuid\nfrom unittest.mock import patch\n\nfrom django.contrib.auth import get_user_model\nfrom django.contrib.auth.models import Group\nfrom django.core.exceptions import ValidationError\nfrom django.test import TestCase,override_settings\nfrom django.urls import reverse\n\nfrom .forms import OrderForm\nfrom .models import StoreLocation,Order,Part,Location,Stock,Event\nfrom .store_directory import read_report,import_report\n\nROW=dict(store_number='20890',address='3947 FEDERAL ST',city='PENNSAUKEN',state='NJ',\n         postal_code='08105-2636',county='Camden County',location_type='Strip')\n\n\n@override_settings(STORAGES={'staticfiles':{'BACKEND':'django.contrib.staticfiles.storage.StaticFilesStorage'}},AXES_ENABLED=False)\nclass StoreDirectoryTests(TestCase):\n    def setUp(self):\n        User=get_user_model()\n        self.office=User.objects.create_user('office')\n        self.office.groups.add(Group.objects.create(name='S3PL Warehouse'))\n        self.customer=User.objects.create_user('fd')\n        self.customer.groups.add(Group.objects.create(name='FD Corporate'))\n        self.other=User.objects.create_user('other')\n        self.store=StoreLocation.objects.create(**ROW)\n\n    def test_search_requires_portal_role_and_import_requires_warehouse(self):\n        self.assertEqual(self.client.get(reverse('store_search'),{'q':'20890'}).status_code,302)\n        self.client.force_login(self.other)\n        self.assertEqual(self.client.get(reverse('store_search'),{'q':'20890'}).status_code,403)\n        self.client.force_login(self.customer)\n        self.assertEqual(self.client.get(reverse('store_search'),{'q':'20890'}).status_code,200)\n        self.assertEqual(self.client.get(reverse('directory_import')).status_code,403)\n        self.client.force_login(self.office)\n        self.assertEqual(self.client.get(reverse('directory_import')).status_code,200)\n\n    def test_zip_preserves_zero_and_returns_choices_excluding_other_customer_and_inactive(self):\n        StoreLocation.objects.create(**(ROW|{'store_number':'20891'}))\n        StoreLocation.objects.create(**(ROW|{'store_number':'20892','active':False}))\n        StoreLocation.objects.create(**ROW,customer_code='OTHER')\n        self.client.force_login(self.customer)\n        r=self.client.get(reverse('store_search'),{'q':'08105'})\n        self.assertEqual(len(r.json()['results']),2)\n        self.assertEqual(r.json()['results'][0]['postal_code'],'08105-2636')\n        self.assertIn('no-store',r['Cache-Control'])\n\n    def test_search_by_city_address_county_and_store_and_limit(self):\n        self.client.force_login(self.customer)\n        for query in ['#20890','2089','Pennsauken NJ','FEDERAL','Camden']:\n            self.assertEqual(self.client.get(reverse('store_search'),{'q':query}).json()['results'][0]['id'],self.store.pk)\n        for n in range(30):\n            StoreLocation.objects.create(**(ROW|{'store_number':str(30000+n)}))\n        data=self.client.get(reverse('store_search'),{'q':'NJ'}).json()\n        self.assertEqual(len(data['results']),20);self.assertTrue(data['more'])\n        self.assertEqual(self.client.get(reverse('store_search'),{'q':''}).json()['results'],[])\n\n    def test_single_digit_and_padded_store_search(self):\n        store=StoreLocation.objects.create(**(ROW|{'store_number':'1'}))\n        self.client.force_login(self.customer)\n        for query in ['1','#1','00001']:\n            self.assertIn(store.pk,[row['id'] for row in self.client.get(reverse('store_search'),{'q':query}).json()['results']])\n\n    def test_selected_store_fills_server_fields_and_order_keeps_snapshot(self):\n        self.client.force_login(self.customer)\n        part=Part.objects.create(sku='TEST-PART',unit='EA')\n        Stock.objects.create(part=part,location=Location.objects.create(code='P1'),kind='PICK',on_hand=10)\n        payload={'store_location':self.store.pk,'store':'WRONG','address':'TAMPERED',\n                 'priority':'NORMAL','request_key':uuid.uuid4(),'sku':part.sku,'quantity':'2','unit':'EA'}\n        response=self.client.post(reverse('new_order'),payload)\n        self.assertEqual(response.status_code,302)\n        order=Order.objects.get()\n        for field,value in self.store.order_details().items(): self.assertEqual(getattr(order,field),value)\n        self.store.address='NEW ADDRESS';self.store.save()\n        order.refresh_from_db();self.assertEqual(order.address,ROW['address'])\n        self.assertContains(self.client.get(reverse('order_detail',args=[order.pk])),ROW['county'])\n\n    def test_invalid_or_inactive_or_other_customer_selection_is_rejected(self):\n        self.client.force_login(self.customer)\n        other=StoreLocation.objects.create(**ROW,customer_code='OTHER')\n        self.store.active=False;self.store.save()\n        for value in ['not-an-id','999999999',str(other.pk),str(self.store.pk)]:\n            form=OrderForm({'store_location':value,**self.store.order_details(),'priority':'NORMAL'})\n            self.assertFalse(form.is_valid());self.assertIn('store_location',form.errors)\n        self.assertFalse(Order.objects.exists())\n\n    def test_manual_delivery_still_works(self):\n        form=OrderForm({**self.store.order_details(),'store_location':'','priority':'NORMAL'})\n        self.assertTrue(form.is_valid(),form.errors)\n        self.assertIsNone(form.cleaned_data['store_location'])\n\n    def test_order_form_contains_search_and_import_link_only_for_office(self):\n        self.client.force_login(self.customer)\n        response=self.client.get(reverse('new_order'))\n        self.assertContains(response,'id=\"store-search\"')\n        self.assertContains(response,'store_lookup.js')\n        self.assertNotContains(response,'Import or update store directory')\n        self.client.force_login(self.office)\n        self.assertContains(self.client.get(reverse('new_order')),'Import or update store directory')\n\n    def test_import_upserts_and_repeated_upload_is_noop_without_touching_stock(self):\n        with patch('warehouse.store_directory.read_report',return_value=[ROW|{'address':'UPDATED'},ROW|{'store_number':'99999'}]):\n            counts=import_report(self.office,b'report-one','report.xlsx')\n            self.assertEqual(counts['created'],1);self.assertEqual(counts['updated'],1)\n            again=import_report(self.office,b'report-one','report.xlsx')\n            self.assertTrue(again['repeated'])\n        self.assertEqual(Event.objects.filter(action='FD_STORE_DIRECTORY_IMPORT').count(),1)\n        self.assertEqual(StoreLocation.objects.count(),2)\n        self.assertFalse(Stock.objects.exists())\n\n    def test_bad_report_does_not_change_directory(self):\n        with self.assertRaises(ValidationError): import_report(self.office,b'not a workbook','bad.xlsx')\n        self.assertEqual(StoreLocation.objects.count(),1);self.assertFalse(Event.objects.exists())\n        with self.assertRaises(PermissionError): import_report(self.customer,b'not a workbook','bad.xlsx')\n\n    def test_later_report_does_not_remove_absent_stores(self):\n        with patch('warehouse.store_directory.read_report',return_value=[ROW|{'store_number':'99999'}]):\n            import_report(self.office,b'new report','new.xlsx')\n        self.store.refresh_from_db();self.assertTrue(self.store.active)\n"
  },
