    "text": "import csv\nfrom django import forms\nfrom django.contrib import messages\nfrom django.core.paginator import Paginator\nfrom django.db.models import Q\nfrom django.http import HttpResponse\nfrom django.shortcuts import get_object_or_404,redirect,render\nfrom django.views.decorators.http import require_POST\nfrom .views import access,ctx\nfrom .models import PickRelease,Order,PurchaseOrder,PurchaseOrderLine,InboundReceipt,InboundReceiptLine\nfrom .services import WorkflowError\nfrom .backorders import change_priority\nfrom .purchase_orders import HEADERS,import_purchase_orders,progress,correct_expected,correct_accepted,correct_receipt_po\n\n\n@access(warehouse=True)\ndef release_detail(request,pk):\n    release=get_object_or_404(PickRelease.objects.select_related('order','receipt'),pk=pk)\n    return render(request,'pick_release.html',ctx(request,release=release,allocations=release.allocations.select_related('line__part','stock__location').order_by('stock__location__code','line__part__sku')))\n\n\n@require_POST\n@access(warehouse=True)\ndef priority(request,pk):\n    get_object_or_404(Order,pk=pk)\n    try: change_priority(request.user,pk,request.POST.get('priority'),request.POST.get('note',''))\n    except WorkflowError as exc: messages.error(request,str(exc))\n    else: messages.success(request,'Priority saved. Urgent orders take priority on the next release; existing reservations stay assigned.')\n    return redirect('order_detail',pk=pk)\n\n\nclass ReportForm(forms.Form):\n    report=forms.FileField(label='PO report (XLSX or CSV)')\n    def clean_report(self):\n        file=self.cleaned_data['report']\n        if file.size>10*1024*1024: raise forms.ValidationError('Use a file under 10 MB.')\n        return file\n\n\n@access(warehouse=True)\ndef purchase_orders(request):\n    form=ReportForm(request.POST or None,request.FILES or None)\n    if request.method=='POST' and form.is_valid():\n        try:\n            file=form.cleaned_data['report'];result=import_purchase_orders(request.user,file.read(),file.name)\n            messages.success(request,'This report was already imported.' if result['unchanged'] else f\"Reviewed {result['orders']} POs; added {result['lines']} expected item lines.\")\n            return redirect('purchase_orders')\n        except WorkflowError as exc: form.add_error(None,str(exc))\n    q=request.GET.get('q','').strip()\n    qs=PurchaseOrder.objects.filter(Q(number__icontains=q)|Q(vendor__icontains=q)).order_by('-created_at')\n    page=Paginator(qs,40).get_page(request.GET.get('page'))\n    return render(request,'purchase_orders.html',ctx(request,form=form,page=page,rows=[progress(po) for po in page],q=q))\n\n\n@access(warehouse=True)\ndef po_template(request):\n    response=HttpResponse(content_type='text/csv; charset=utf-8')\n    response['Content-Disposition']='attachment; filename=\"FD_PO_import_template.csv\"'\n    csv.writer(response).writerow(HEADERS)\n    return response\n\n\n@access(warehouse=True)\ndef po_detail(request,pk):\n    po=get_object_or_404(PurchaseOrder,pk=pk)\n    if request.method=='POST':\n        line=get_object_or_404(PurchaseOrderLine,pk=request.POST.get('line'),purchase_order=po)\n        try: correct_expected(request.user,line.pk,request.POST.get('expected'),request.POST.get('note',''))\n        except WorkflowError as exc: messages.error(request,str(exc))\n        else: messages.success(request,'Expected quantity corrected and recorded in history.')\n        return redirect('po_detail',pk=pk)\n    from .models import InboundReceipt\n    return render(request,'po_detail.html',ctx(request,**progress(po),receipts=InboundReceipt.objects.filter(Q(po_number=po.number)|Q(lines__po_number=po.number)).distinct()))\n\n\n@require_POST\n@access(warehouse=True)\ndef accepted(request,pk):\n    line=get_object_or_404(InboundReceiptLine,pk=pk)\n    try: correct_accepted(request.user,pk,request.POST.get('accepted'),request.POST.get('note',''),request.POST.get('po_number'))\n    except WorkflowError as exc: messages.error(request,str(exc))\n    else: messages.success(request,'PO accepted quantity updated with an audit record. Stock quantities and the original receipt email were not changed.')\n    return redirect('receipt_detail',pk=line.receipt_id)\n\n\n@require_POST\n@access(warehouse=True)\ndef receipt_po(request,pk):\n    get_object_or_404(InboundReceipt,pk=pk,status='POSTED')\n    try: correct_receipt_po(request.user,pk,request.POST.get('po_number',''),request.POST.get('note',''))\n    except WorkflowError as exc: messages.error(request,str(exc))\n    else: messages.success(request,'Receipt PO reference corrected with an audit record. The original customer email remains unchanged.')\n    return redirect('receipt_detail',pk=pk)\n"
  },
