    "text": "\"\"\"Private, one-time FD inventory correction approved on November 13, 2026.\n\nOnly untouched ICC import balances are eligible. No counts, messages, orders,\nor customer records are created. Approved location data is supplied privately through Render configuration.\n\"\"\"\nimport os\nimport json\nimport hashlib\nfrom collections import Counter\nfrom decimal import Decimal\nfrom django.contrib.auth import get_user_model\nfrom django.db import transaction\nfrom warehouse.models import Part, Stock, Location, Event, OrderLine, Allocation\nfrom warehouse.services import warehouse_user\n\nIMPORT_ID = '5fddbc5d-3ec2-4bcb-a774-af4d2d73d5ea'\nAPPROVAL_ID = 'FD-BINS-2026-11-13-CHRIS-COLIN'\nENV_NAME = 'S3PL_FD_BIN_APPROVAL_JSON'\nEXPECTED_PAYLOAD_SHA256 = '6cf7c1e147864ec0a9642f2327baa2782a8a6bdebfe2d02dc33539533f27a4d5'\n\n\ndef validated_approval(raw):\n    if not raw or len(raw) > 65536:\n        raise ValueError('A valid private bin-approval configuration is required.')\n    try:\n        data = json.loads(raw)\n        canonical = json.dumps(data, sort_keys=True, separators=(',', ':')).encode()\n    except (ValueError, TypeError) as exc:\n        raise ValueError('Invalid private bin-approval configuration.') from exc\n    if hashlib.sha256(canonical).hexdigest() != EXPECTED_PAYLOAD_SHA256:\n        raise ValueError('Bin-approval configuration does not match the reviewed update; nothing changed.')\n    return data\n\n\ndef apply_updates(actor_name='colin', apply=True):\n    APPROVAL_DATA = validated_approval(os.environ.get(ENV_NAME, ''))\n    SOURCE_NAME = APPROVAL_DATA['source']\n    actor = get_user_model().objects.get(username=actor_name, is_active=True)\n    if not warehouse_user(actor):\n        raise PermissionError('The audit user needs S3PL warehouse access.')\n    records = APPROVAL_DATA['records']\n    report = []\n    with transaction.atomic():\n        # Existing stock-changing workflows also lock Part before Stock.\n        parts = {p.sku: p for p in Part.objects.select_for_update().filter(\n            sku__in=[r['sku'] for r in records]).order_by('pk')}\n        for record in records:\n            sku = record['sku']\n            part = parts.get(sku)\n            target = record['approved_bin']\n            disposed = record['disposed']\n            def add(status, detail):\n                report.append({'sku': sku, 'status': status, 'detail': detail})\n            if part is None:\n                add('REVIEW', 'Part not found; nothing changed.')\n                continue\n            if Event.objects.filter(stock__part=part,\n                    entry__approval_id=APPROVAL_ID).exists():\n                add('ALREADY APPLIED', 'This approval was recorded previously; later activity preserved.')\n                continue\n            stocks = list(Stock.objects.select_for_update().filter(part=part)\n                          .select_related('location').order_by('pk'))\n            originals = list(Event.objects.filter(stock__part=part,\n                action='ICC_TEST_IMPORT', entry__import_id=IMPORT_ID).order_by('pk'))\n            if not stocks or len(originals) != len(stocks) or \\\n                    {e.stock_id for e in originals} != {s.pk for s in stocks}:\n                add('REVIEW', 'Stock records differ from the original ICC import; nothing changed.')\n                continue\n            by_stock = {e.stock_id: e for e in originals}\n            expected_bins = {record['approved_bin'], record['rejected_bin']}\n            if any({str(e.entry.get('source', {}).get(k, '')).strip()\n                    for k in ('L', 'O')} != expected_bins for e in originals):\n                add('REVIEW', 'Source bins do not match the approved email; nothing changed.')\n                continue\n            if part.unit != 'EA' or OrderLine.objects.filter(part=part).exists() or \\\n                    Allocation.objects.filter(stock__part=part).exists():\n                add('REVIEW', 'Orders/allocations exist or base unit changed; nothing changed.')\n                continue\n            if Event.objects.filter(stock__part=part).exclude(\n                    pk__in=[e.pk for e in originals]).exists():\n                add('REVIEW', 'Activity after the ICC import; nothing changed.')\n                continue\n            if any(s.archived or s.reserved or s.held or s.count_required or\n                    s.last_counted_at is not None or s.on_hand is None or\n                    s.on_hand != by_stock[s.pk].after for s in stocks):\n                add('REVIEW', 'Balances, holds, counts or archive status changed; nothing changed.')\n                continue\n            if len({s.kind for s in stocks}) != 1:\n                add('REVIEW', 'Pick/overstock classification differs between bins; nothing changed.')\n                continue\n            total = sum((s.on_hand for s in stocks), Decimal(0))\n            old = [{'stock_id': s.pk, 'bin': s.location.code,\n                    'on_hand': str(s.on_hand), 'kind': s.kind} for s in stocks]\n            if not apply:\n                add('READY', f'Disposed: {total} EA to 0 EA; retain history.' if disposed\n                    else f'{target}: retain total {total} EA.')\n                continue\n            if disposed:\n                for stock in stocks:\n                    before = stock.on_hand\n                    stock.on_hand = Decimal(0)\n                    stock.archived = True\n                    stock.save(update_fields=['on_hand', 'archived'])\n                    Event.objects.create(actor=actor, stock=stock, action='DISPOSAL',\n                        before=before, after=Decimal(0), quantity=-before,\n                        entry={'approval_id': APPROVAL_ID, 'source': SOURCE_NAME,\n                               'source_sha256': APPROVAL_DATA['source_sha256'],\n                               'prior_bins': old, 'disposal_confirmed': True,\n                               'already_zero': before == 0, 'archived': True},\n                        note='Colin confirmed Chris Sobota\\'s disposal notice on 2026-11-13. '\n                             'This records disposal, not a physical count. No disposal date was inferred.')\n                add('DISPOSAL RECORDED', f'{total} EA before; 0 EA after. Empty stock records archived; history retained.')\n                continue\n            location, _ = Location.objects.get_or_create(code=target)\n            keep = next((s for s in stocks if s.location_id == location.pk), stocks[0])\n            for stock in stocks:\n                before = stock.on_hand\n                if stock.pk == keep.pk:\n                    stock.location = location\n                    stock.on_hand = total\n                else:\n                    stock.on_hand = Decimal(0)\n                    stock.archived = True\n                stock.save(update_fields=['location', 'on_hand', 'archived'])\n                Event.objects.create(actor=actor, stock=stock, action='ICC_LOCATION_CORRECTION',\n                    before=before, after=stock.on_hand, quantity=stock.on_hand-before,\n                    entry={'approval_id': APPROVAL_ID, 'source': SOURCE_NAME,\n                           'source_sha256': APPROVAL_DATA['source_sha256'],\n                           'target': target, 'prior_bins': old, 'archived': stock.archived},\n                    note='Green-highlighted bin approved by Colin from Chris Sobota\\'s 2026-11-13 email. '\n                         'Part total preserved. Not a receipt, transfer, or physical count.')\n            add('LOCATION UPDATED', f'{target}; total {total} EA preserved.')\n    return report\n\n\ndef run_configured_approval(stdout):\n    if not os.environ.get(ENV_NAME, '').strip():\n        return []\n    report = apply_updates()\n    for row in report:\n        stdout.write(f\"{row['status']} | {row['sku']} | {row['detail']}\")\n    stdout.write('FD BIN APPROVAL SUMMARY: ' + str(dict(Counter(row['status'] for