def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    root=Path(__file__).resolve().parent
    if not (root/'manage.py').is_file() or not (root/'warehouse').is_dir():
        raise SystemExit('Upload build (3).sh alongside manage.py in the repository root.')
    changes=[];conflicts=[]
    for name,record in FILES.items():
        relative=Path(name)
        if relative.is_absolute() or '..' in relative.parts:
            raise SystemExit('Invalid update path.')
        target=root/relative
        if target.is_symlink() or root not in target.resolve().parents:
            raise SystemExit('Update target is outside the repository.')
        data=record['text'].encode('utf-8') if 'text' in record else base64.b64decode(record['base64'],validate=True)
        if hashlib.sha256(data).hexdigest()!=record['sha256']:
            raise SystemExit('Update contents failed validation: '+name)
        current=hashlib.sha256(target.read_bytes()).hexdigest() if target.is_file() else None
        if current==record['sha256']:continue
        if current not in record['previous']:conflicts.append(name)
        changes.append((target,data))
    if conflicts:
        raise SystemExit('STOPPED: unexpected edits; no files written. Send these names for a merged update: '+', '.join(conflicts))
    if args.check:
        print(f'Update validated: {len(changes)} files would change; {len(FILES)-len(changes)} already current.')
        return
    for target,data in changes:
        target.parent.mkdir(parents=True,exist_ok=True)
        temporary=target.with_name(target.name+'.wms-update-tmp')
        temporary.write_bytes(data)
        os.replace(temporary,target)
    print(f'S3PL FD WMS brand update 2026.11.13 installed: {len(changes)} files changed; {len(FILES)-len(changes)} already current.')

if __name__=='__main__':main()

